quests[52888] = { id = 52888, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Tiefgrüne Höhle", description = "Der Überfall, den Ihr auf die Tiefgrüne Höhle in Zuldazar geplant habt, war erfolgreich. Gut gemacht.\n\nDer Außenposten ist bereit zur Übernahme.\n\nMacht Euch auf den Weg zur Tiefgrünen Höhle in Zuldazar und baut dort Befestigungsanlagen.\n\nDie Tiefgrüne Höhle wird als Außenposten eine entscheidende Rolle in unserer Kampagne gegen die Horde spielen.\n\nFür die Allianz!", sourceObjective = "Beansprucht die Tiefgrüne Höhle für die Allianz.", completion = "Hier ist der perfekte Standort für einen Außenposten. In der Nähe sind Azeritvorkommen und viele große Tiere zum Jagen gibt es auch!", sourceObjectiveStatus = "unverified-source-field" }
