quests[52928] = { id = 52928, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spenden für das Arathihochland: Raues Leder", progress = "Ich hab gehört, dass unsere Ledervorräte langsam zur Neige gehen. Jede Spende wäre also herzlichst willkommen.", completion = "Mit einer Spende wie dieser rettet Ihr uns wahrlich unsere Haut." }
quests[52929] = { id = 52929, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spenden für das Arathihochland: Moneliterz", progress = "Die Versorgung mit Erz ist der Schlüssel zu einem kontinuierlichen Fluss von Rüstung und Waffen.", completion = "Heh. Eine sehr großzügige Menge an Erz.\n\nDas wird unsere Schmiede für eine Weile beschäftigen." }
quests[52930] = { id = 52930, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spenden für das Arathihochland: Gold", description = "Unsere Freunde hier akzeptieren alle möglichen Spenden für unsere Kriegsanstrengungen, aber wenn Ihr mich fragt, wurde noch nie ein Krieg ohne angemessene Finanzierung gewonnen. Ja, genau. Ich rede von Geld! Und zwar eine Menge davon.\n\nWenn Ihr es habt, brauchen wir es!", sourceObjective = "Spendet 1000000 Gold an Zahlmeister Grinsebacke im Hafen von Zandalar.", progress = "Ein {class} wie Ihr hat doch sicherlich etwas Bargeld beiseitegeschafft.\n\nWas meint Ihr? Soll ich Euch ein wenig von Eurer Last befreien?", completion = "Gibt doch nichts Wertvolleres als süßes, süßes Gold.", sourceObjectiveStatus = "unverified-source-field" }
