quests[52942] = { id = 52942, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alte Bande neu knüpfen", description = "Wir müssen mit Grommash Höllschrei sprechen und ihn daran erinnern, dass er in unserer Schuld steht. Alles hängt von dieser Mission ab, {name}.\n\nIch hoffe, dass Eure diplomatischen Fähigkeiten besser sind als meine.\n\nSeid auf der Hut. Wir wissen nicht, was uns auf der anderen Seite erwartet.", sourceObjective = "Sprecht mit Oculeth, um nach Draenor zu reisen und die Mag'har zu treffen.", completion = "Noch sind wir nicht tot. Das ist ein gutes Zeichen, glaube ich.", sourceObjectiveStatus = "unverified-source-field" }
quests[52943] = { id = 52943, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Respekt für die Klans", description = "Diese Oberanführerin Geya'rah hat ganz schön Feuer. Mit der könnte ich mich anfreunden... wenn sie uns nicht tötet.\n\nWir haben nur eine Chance. Ihr zollt den Symbolen jedes einzelnen Klans Anerkennung und ich werde darüber sprechen.\n\nZeigt Respekt... sonst werden sie uns die Klinge des Scharfrichters zeigen.", sourceObjective = "Zollt den Symbolen der Orcklans Anerkennung.", progress = "Für so etwas habe ich jetzt keine Zeit.", completion = "Ihr kennt Euch also mit unseren Klans aus.", sourceObjectiveStatus = "unverified-source-field" }
quests[52944] = { id = 52944, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf zu den Waffen: Drustvar", description = "Wir haben zunehmende Hordenaktivität in Drustvar festgestellt. Wir dürfen nicht zulassen, dass sie die Oberhand gewinnt.", sourceObjective = "Tötet Mitglieder der Horde in Drustvar.", completion = "Großartige Arbeit, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[52945] = { id = 52945, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bindungen, im Kampf geschmiedet", description = "Geya'rah hat ein feuriges Temperament... wie ihre Mutter. Vielleicht wird es ihren Argwohn besänftigen, dass wir uns einem gemeinsamen Feind gegenübersehen.\n\nWir haben die Ogerklans schon vor Langem unterworfen. Doch hin und wieder entfacht einer ihrer Tapfersten... oder Dümmsten... den Funken der Rebellion. Heute ist so ein Tag.\n\nIhr und Etrigg werdet Euch Geya'rah anschließen, um den Ogeraufstand niederzuschlagen. Beweist Euch im Kampf und vielleicht verdient Ihr Euch ihren Respekt.", sourceObjective = "Helft Geya'rah dabei, den Ogeraufstand niederzuschlagen.", progress = "Haltet mich nicht auf.", completion = "Wir müssen uns alle paar Monate um Ogeraufstände kümmern.", sourceObjectiveStatus = "unverified-source-field" }
quests[52946] = { id = 52946, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine sterbende Welt", description = "Champion, Azeroth wird sterben, während die Armeen der Horde und der Allianz um eine Stadt in Ruinen kämpfen.\n\nSie braucht Eure Hilfe. Macht Euch auf den Weg zu meinem Lager in Silithus. Azeroth möchte Euch etwas geben.", sourceObjective = "Trefft Magni Bronzebart in Silithus in Kalimdor.", completion = "Da seid Ihr ja. Wir haben keine Zeit zu verlieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[52947] = { id = 52947, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In den Hintern trettin" }
