quests[52955] = { id = 52955, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tyrannei des Lichts", description = "Wenn es kein Ogeraufstand ist oder die Aussicht auf den Hungertod, ist es die ständige Bedrohung durch die Lichtgebundenen.\n\nSollten sich die Berichte als wahr erweisen, dann haben sie sich so nah wie noch nie an unsere Festung herangewagt.\n\nKommt mit oder bleibt hier, aber Ihr müsst Euch schnell entscheiden.", sourceObjective = "Helft Geya'rah gegen die Tyrannei des Lichts.", completion = "Wenn ich an jene denke, die wir gerade verloren haben... Es ist... nein, das ist zwecklos.", sourceObjectiveStatus = "unverified-source-field" }
quests[52956] = { id = 52956, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf zu den Waffen: Tiragardesund", description = "Es ist Zeit, die Allianz an der Quelle zu treffen. Reist zum Tiragardesund und tötet jedes Mitglied der Allianz, das Ihr finden könnt. Auf ihrem eigenen Territorium sollten sie nicht weiter schwer zu finden sein.", sourceObjective = "Tötet Mitglieder der Allianz im Tiragardesund.", completion = "Gute Arbeit, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[52957] = { id = 52957, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf zu den Waffen: Sturmsangtal", description = "Es ist Zeit, die Allianz an der Quelle zu treffen. Reist ins Sturmsangtal und tötet jedes Mitglied der Allianz, das Ihr finden könnt. Auf ihrem eigenen Territorium sollten sie nicht weiter schwer zu finden sein.", sourceObjective = "Tötet Mitglieder der Allianz im Sturmsangtal.", completion = "Gute Arbeit, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[52958] = { id = 52958, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf zu den Waffen: Drustvar", description = "Es ist Zeit, die Allianz an der Quelle zu treffen. Reist nach Drustvar und tötet jedes Mitglied der Allianz, das Ihr finden könnt. Auf ihrem eigenen Territorium sollten sie nicht weiter schwer zu finden sein.", sourceObjective = "Tötet Mitglieder der Allianz in Drustvar.", completion = "Gute Arbeit, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[52962] = { id = 52962, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Missionsbericht: Nebelschlingenvorsprung", description = "Eure Anhänger haben Euch einen Bericht über einen Angriff auf den Nebelschlingenvorsprung geschickt.\n\nDarin steht, dass es ein hart errungener Sieg war und alle Feinde um den Außenposten herum getötet wurden.\n\nBringt den Bericht zu Hochkommandant Wyrmbann an Bord der Erlösenden Winde.", sourceObjective = "Bringt den Bericht über Euren Sieg zu Halford Wyrmbann.", progress = "Gibt es Neuigkeiten über die Mission nach Zuldazar?", completion = "Die Mission, in Zuldazar einen zusätzlichen Stützpunkt zu errichten, war wohl von Erfolg gekrönt. Gut gemacht, {name}.\n\nIch werde Euch entsenden, damit Ihr den Bau der Befestigungsanlagen beaufsichtigt.", sourceObjectiveStatus = "unverified-source-field" }
quests[52963] = { id = 52963, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Nebelschlingenvorsprung", description = "Der Überfall, den Ihr auf den Nebelschlingenvorsprung in Zuldazar geplant habt, war erfolgreich. Gut gemacht.\n\nDer Außenposten ist bereit zur Übernahme.\n\nMacht Euch auf den Weg zum Nebenschlingenvorsprung in Zuldazar und baut dort Befestigungsanlagen.\n\nDer Nebelschlingenvorsprung wird als Außenposten eine entscheidende Rolle in unserer Kampagne gegen die Horde spielen.\n\nFür die Allianz!", sourceObjective = "Beansprucht den Nebelschlingenvorsprung für die Allianz.", completion = "Seid gegrüßt, {name}. Der Nebelschlingenvorsprung wird mit Sicherheit einer unserer wertvollsten Außenposten werden. Wir haben direkten Ausblick auf den Goldenen Thron, und das Blätterdach des Dschungels bietet reichlich Tarnung.", sourceObjectiveStatus = "unverified-source-field" }
quests[52964] = { id = 52964, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ungezieferproblem" }
quests[52965] = { id = 52965, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Winterhauchgeschenk", sourceObjective = "Auf dem Schildchen am Geschenk steht:\n\nFrohe Feiertage, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[52967] = { id = 52967, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Saurfangs Rückkehr", description = "Saurfang! Das wurde auch Zeit.\n\nSeht Euch um, <Held/Heldin>! Welch wunderschöner Anblick: Die Irrwische zerstreuen sich. Die Mauern fallen eine nach der anderen.\n\nDie Zeit ist gekommen. Der Weltenbaum gehört uns! Sucht Saurfang. Wir setzen dem ein für alle Mal ein Ende.", sourceObjective = "Findet Saurfang in Lor'danel.", completion = "Unser Weg war gefährlich, aber wir haben unser Ziel nie aus den Augen verloren.", sourceObjectiveStatus = "unverified-source-field" }
quests[52968] = { id = 52968, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zeit für ein bisschen Blutvergießen" }
quests[52970] = { id = 52970, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lasst keine Gnade walten", description = "Ich werde keine Unschuldigen umbringen. Solange sie nicht ihre Waffen gegen uns erheben, werden wir sie verschonen.\n\nGeht nach Lor'danel und nehmt alle Zivilisten gefangen, die Ihr vorfindet. Wir werden sie verhören und anschließend freilassen.", sourceObjective = "Nehmt 8 Einwohner von Lor'danel gefangen.", completion = "Wir sind unseren Feinden heute mit Ehre begegnet.", sourceObjectiveStatus = "unverified-source-field" }
quests[52971] = { id = 52971, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rendezvous an der Küste", description = "An der Küste in Lor'danel sind beträchtliche Verstärkungen stationiert. Genug um uns wieder zurückzudrängen.\n\nAber mit einem schnellen Schlag können wir diese Bedrohung ausschalten!\n\nDurchbrecht ihre Linien und tötet ihre beiden Anführer. Ohne Führung wird ihre Streitmacht in sich zusammenfallen.", sourceObjective = "Tötet Caranne Dornenbogen und Ariel Hirschwacht.", completion = "Ich gratuliere Euch zu Eurem Erfolg, aber ich spüre, dass etwas nicht stimmt...", sourceObjectiveStatus = "unverified-source-field" }
quests[52972] = { id = 52972, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lieblingsenkel" }
quests[52973] = { id = 52973, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bedrohung aus dem Norden", description = "Die Horde muss die Berge des Teufelswalds im Norden erklommen haben.\n\nDie Mauer der Irrwische fällt und es ist nur eine Frage der Zeit, bevor die Horde durchbricht. Sie werden uns in die Zange nehmen.\n\nWir müssen diesen Angriff gemeinsam durchstehen.", sourceObjective = "Findet Malfurion Sturmgrimm in Lor'danel.", completion = "Ganz gleich, wie schlecht die Chancen stehen, wir müssen stark bleiben.", sourceObjectiveStatus = "unverified-source-field" }
quests[52974] = { id = 52974, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rettungsmission", description = "Die Plötzlichkeit des Angriffs der Horde gab den Einwohnern kaum Zeit zur Flucht. Viele halten sich noch immer in Lor'danel versteckt und warten auf ihre Rettung. \n\nFindet die Zivilisten und bringt sie in Sicherheit. Wir zählen auf Euch, {name}.", sourceObjective = "Rettet 8 Einwohner von Lor'danel.", completion = "Ihr habt heute viele Leben gerettet, {name}. Habt Dank.", sourceObjectiveStatus = "unverified-source-field" }
quests[52975] = { id = 52975, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sofort handeln", description = "Feindliche Truppen unter Führung zwei der stärksten Krieger der Horde versuchen unsere Flotte zu kapern. Wir dürfen das nicht zulassen, {name}.\n\nWenn sie es schaffen, uns unsere Schiffe zu nehmen, werden sie damit nach Darnassus übersetzen.\n\nTötet die beiden Krieger, die den Angriff anführen. Dann wird sich der Rest zweifelsohne zurückziehen.", sourceObjective = "Tötet Gormok Axtfall und Ragash Blutwunsch.", completion = "Habt Ihr in letzter Zeit etwas von Malfurion gehört?", sourceObjectiveStatus = "unverified-source-field" }
quests[52977] = { id = 52977, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mit der Führung unseres Shan'do", description = "Lor'danel wird überrannt. Die Horde... Sie... sie gibt einfach nicht nach.\n\nWir können nichts tun, {name}. Wir müssen unseren Shan'do finden und um seine Führung bitten.\n\nEr ist der Einzige, der uns retten kann.", sourceObjective = "Findet Malfurion Sturmgrimm an der Dunkelküste.", completion = "{name}! Der Baum...", sourceObjectiveStatus = "unverified-source-field" }
quests[52978] = { id = 52978, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prinz im Schlepptau", description = "Setzen wir Segel nach Zandalar. Falls es Euch entgangen ist: Wir mussten uns mit Einmischung von Seiten der Allianz herumschlagen, während Ihr weg wart.", sourceObjective = "Sprecht mit Schreckensadmiralin Segelriss, um nach Zuldazar zurückzukehren.", completion = "Wieder einmal ausgezeichnete Arbeit, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[52979] = { id = 52979, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reinigungsritual" }
quests[52981] = { id = 52981, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mörderische Königin", description = "Lor'danel ist jetzt sicher, aber irgendetwas fehlt noch... Es war keine Spur von Sturmgrimm zu sehen.\n\nMalfurion hätte niemals Lor'danel kampflos fallen lassen. Er muss ihre Verfolgung aufgenommen haben.\n\nMeine Armee ist von Norden her gekommen und unsere Verstärkung ist aus dem Süden eingetroffen. Das bedeutet, dass sie sich nicht auf irgendeiner der Straßen befinden.\n\nDurchsucht mit mir den Wald, {name}. Wir werden sie finden und das ein für alle Mal erledigen.", sourceObjective = "Durchsucht den Wald der Dunkelküste, um den Kriegshäuptling zu finden.", completion = "<Die Flammen hüllen Sylvanas' Antlitz in Schatten.>", sourceObjectiveStatus = "unverified-source-field" }
quests[52982] = { id = 52982, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Böse Mine" }
quests[52983] = { id = 52983, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ich will alles", description = "Ein Elementar aus reinem Azerit! Ich weiß nicht, wie groß diese Bedrohung ist, Champion... aber bitte seid vorsichtig.", sourceObjective = "Bezwingt den Azeritfuror.", sourceObjectiveStatus = "unverified-source-field" }
quests[52984] = { id = 52984, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ich will alles", description = "Ein Elementar... aus reinem Azerit. Bezwingt ihn, Champion, aber zerstört ihn nicht. Wir brauchen das Azerit.", sourceObjective = "Bezwingt den Azeritfuror.", sourceObjectiveStatus = "unverified-source-field" }
quests[52986] = { id = 52986, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein tückisches Gefäß" }
quests[52987] = { id = 52987, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alles soll brennen!" }
quests[52988] = { id = 52988, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hausputz" }
quests[52990] = { id = 52990, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zum Hafen zurückkehren", description = "Wir haben das Szepter in der Hand, also lasst uns zum Portal zurückkehren.\n\nStein würde mir sicher zustimmen, dass es für uns das Beste ist, wenn wir uns eine Weile von Kul Tiras fernhalten.", sourceObjective = "Kehrt zu Nathanos Pestrufer in Raubhafen zurück.", completion = "Anscheinend war Eure Mission erfolgreich. Gut.", sourceObjectiveStatus = "unverified-source-field" }
quests[53003] = { id = 53003, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Teufelskreis", description = "Wir haben neue Champions für die Horde ausgehoben, Stützpunkte in Kul Tiras errichtet und eins ihrer wertvollen Artefakte gestohlen.\n\nWir haben mehr Macht und Einfluss über unsere Feinde als je zuvor.\n\nSylvanas hat große Pläne für unsere Horde, {name}. Ich werde Euch das Vergnügen zugestehen, ihr persönlich über unsere Siege Bericht zu erstatten.", sourceObjective = "Meldet Euch bei Sylvanas Windläufer in Orgrimmar.", completion = "{name}. Nathanos hat mir vom Fortschritt Eurer Bemühungen berichtet.\n\nDie Allianz und die Kul Tiraner sollen vor der Macht meiner Horde erzittern.", sourceObjectiveStatus = "unverified-source-field" }
quests[53006] = { id = 53006, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Missionsbericht: Grimmwatts Sturz", description = "Eure Anhänger haben Euch einen Bericht über eine Rettungsmission nach Grimmwatts Sturz geschickt.\n\nDarin steht, dass es ein hart errungener Sieg war und alle Feinde um die Absturzstelle herum getötet wurden.\n\nBringt den Bericht zu Hochkommandant Wyrmbann an Bord der Erlösenden Winde.", sourceObjective = "Bringt den Bericht über Euren Sieg zu Halford Wyrmbann.", progress = "Gibt es Neuigkeiten über die Mission nach Nazmir?", completion = "Die Mission bei Grimmwatts Sturz war wohl von Erfolg gekrönt. Gut gemacht, {name}.\n\nDas wird ein ausgezeichneter Außenposten werden. Ich werde Euch entsenden, damit Ihr den Bau der Befestigungsanlagen beaufsichtigt.", sourceObjectiveStatus = "unverified-source-field" }
quests[53007] = { id = 53007, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grimmwatts Sturz", description = "Die Rettungsaktion, die Ihr für Grimmwatts Sturz in Nazmir geplant habt, war erfolgreich. Gut gemacht.\n\nIch denke, wir sollten die Absturzstelle befestigen und sie in einen Außenposten umwandeln.\n\nMacht Euch auf den Weg nach Grimmwatts Sturz und baut dort Befestigungsanlagen.\n\nGrimmwatts Sturz wird als Außenposten eine entscheidende Rolle in unserer Kampagne gegen die Horde spielen.\n\nFür die Allianz!", sourceObjective = "Beansprucht Grimmwatts Sturz für die Allianz.", completion = "Die Absturzstelle war bei unserem Eintreffen umzingelt. Wie gut, dass wir es rechtzeitig geschafft haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[53008] = { id = 53008, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Klugheit eines Weisen" }
quests[53009] = { id = 53009, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Haltet durch", description = "Ein Elementar... aus reinem Azerit. Bezwingt ihn, Champion, aber zerstört ihn nicht. Wir brauchen das Azerit.", sourceObjective = "Bezwingt den Azeritfuror.", sourceObjectiveStatus = "unverified-source-field" }
quests[53010] = { id = 53010, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kein Zurück", description = "Ein Elementar... aus reinem Azerit. Bezwingt ihn, Champion, aber zerstört ihn nicht. Wir brauchen das Azerit.", sourceObjective = "Bezwingt den Azeritfuror.", sourceObjectiveStatus = "unverified-source-field" }
quests[53011] = { id = 53011, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein leicht geschütteltes Geschenk", sourceObjective = "Dieses Geschenk sieht aus, als wäre es schon ein paar Mal geschüttelt worden. Auf dem Kärtchen steht:\n\nFür {name}, ein ganz besonderer {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[53012] = { id = 53012, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spielzeuge wegräumen" }
quests[53025] = { id = 53025, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausdünnung" }
quests[53027] = { id = 53027, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Am Rande des Ruhms" }
quests[53028] = { id = 53028, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine sterbende Welt", description = "Champion. Magni Bronzebart benötigt Eure Hilfe.\n\nAzeroth stirbt. Vor diesem Krieg hat ein riesiger Dämon namens Sargeras den Planeten mit einem Schwert durchbohrt.\n\nUnser Planet schreit vor Schmerz, während Horde und Allianz sich gegenseitig bekämpfen.\n\nMagni Bronzebart glaubt, dass Ihr ihm helfen könnt, die Wunden des Planeten zu heilen.\n\nTrefft ihn in Silithus. Er hat ein Lager an der Stelle errichtet, an der Sargeras' sein Schwert in unsere Welt gebohrt hat.", sourceObjective = "Trefft Magni Bronzebart in Silithus in Kalimdor.", completion = "Da seid Ihr ja. Wir haben keine Zeit zu verlieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[53030] = { id = 53030, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Welt wartet", description = "Wenn das Zeichen des Abgesandten am Nachthimmel leuchtet, festigen die Sterne ihre bestehenden Bande und knüpfen neue. Freundschaft wird nicht leichtfertig vergeben und nur durch Taten wird Treue bewiesen, aber Vertrauen stellt sich in diesen Tagen schneller ein. Bereist diese Region und helft, wo Ihr könnt, um Euch als würdig zu erweisen.", sourceObjective = "Schließt 20 Weltquests in Kul Tiras, Zandalar, an der Dunkelküste, im Arathihochland oder in Nazjatar ab.", completion = "Gut gemacht, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[53031] = { id = 53031, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Gebot des Sprechers", description = "Die Seele der Welt ist vorerst sicher. Ich kann Azeroth wieder hören, obwohl ihre Stimme immer noch schwach ist.\n\nDie Elementare auf der Oberfläche haben sich wieder beruhigt. Das Herz von Azeroth hat diesen Ort wieder stabilisiert, obwohl es nur über einen Bruchteil seiner Macht verfügt hat.\n\nKehrt nach Orgrimmar zurück. Setzt Eure Verbündeten über das, was hier geschehen ist, ins Bild. Erinnert sie daran, dass ganz gleich, was in ihrem Krieg passiert, unsere Welt gerettet werden muss.\n\nWir sprechen uns bald wieder, {name}. Der Kampf um Azeroth hat gerade erst begonnen.", sourceObjective = "Sprecht mit Nathanos Pestrufer in Orgrimmar.", completion = "Man könnte sagen, Ihr wart zur rechten Zeit am rechten Ort, {name}. Dieses Herz von Azeroth, das der Zwerg Euch gegeben hat, könnte sich noch als sehr nützlich erweisen.\n\nDoch unser Hauptaugenmerk muss weiterhin auf dem Krieg liegen. Wir können keine Streitkräfte erübrigen, um Magni bei seinem großen Kreuzzug zu unterstützen.\n\nDie Allianz wird vor nichts zurückschrecken, um die Horde zu vernichten. Zum Glück hat die Dunkle Fürstin einen Plan, um uns zu stärken.", sourceObjectiveStatus = "unverified-source-field" }
quests[53032] = { id = 53032, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein brennender Pfad durch die Zeit", description = "Der gleißende Stern wirft sein Licht auf das Land und lässt die Erde verdorren und ganze Landschaften versengen. Es ist ein gnadenloser, fast schon bösartiger Stern. Unter seinem Einfluss eröffnen sich neue Wege - zu weit entfernten Orten und sogar zu weit entfernten Zeiten. Kein Weiser ist in der Lage, die Bedeutung dieses Zeichens vollständig zu verstehen, aber das Glück ist mit den Mutigen.", sourceObjective = "Schließt 5 Zeitwanderungsdungeons ab.", completion = "Ah, {name}. Ihr seid zurück. Euch umgibt wahrlich eine Aura aus einer anderen Welt.", sourceObjectiveStatus = "unverified-source-field" }
quests[53033] = { id = 53033, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein gefrorener Weg durch die Zeit", description = "Der kalte Stern wirft sein frostiges Licht auf das Land und selbst die Schatten ziehen sich zurück. Es ist ein Stern wie kein zweiter, der alle Wärme und Leben entzieht. Unter seinem Einfluss eröffnen sich neue Wege - zu weit entfernten Orten und sogar zu weit entfernten Zeiten. Kein Weiser ist in der Lage, die Bedeutung dieses Zeichens vollständig zu verstehen, aber das Glück ist mit den Mutigen.", sourceObjective = "Schließt 5 Zeitwanderungsdungeons ab.", progress = "Ich habe in der Zukunft gesehen, dass Ihr einem kalten Stern auf dem von ihm aufgezeigten Weg folgen werdet.", completion = "Ah, {name}. Ihr seid zurück. Euch umgibt wahrlich eine Aura aus einer anderen Welt.", sourceObjectiveStatus = "unverified-source-field" }
quests[53034] = { id = 53034, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein verwüsteter Pfad durch die Zeit", description = "Der Stern des Zerstörers bedeckt das Land mit seinem durchdringenden Licht, sodass sich selbst die Geister in die Schatten zurückziehen. Dieser Stern ist wie kein anderer am Himmel. Er offenbart selbst die Schwächen der furchtlosesten Helden. Solange er am Himmel steht, können sich neue Pfade zu fernen Orten oder sogar Zeiten eröffnen. Die Gelehrten sind ratlos, was die Natur dieses Zeichens betrifft, doch das Glück belohnt bekanntlich die Mutigen.", sourceObjective = "Schließt 5 Zeitwanderungsdungeons ab.", completion = "Ah, {name}. Ihr seid zurück. Euch umgibt wahrlich eine Aura aus einer anderen Welt.", sourceObjectiveStatus = "unverified-source-field" }
quests[53035] = { id = 53035, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein verschleierter Pfad durch die Zeit", description = "Der verschleierte Stern lässt sein Flackern durch die flüsternden Wogen der gespenstischen Nebel gleiten. Wie ein düsterer Schleier legt sich das Schauspiel über die Geheimnisse und Gefahren des Landes und eröffnet neue Pfade zu fernen Orten, gar Zeiten, bis sein Lichtspiel still entschwindet. Kein Weiser kann die Natur dieses Omens wahrhaft begreifen, doch das Glück ist bekanntlich mit den Mutigen.", sourceObjective = "Schließt 5 Zeitwanderungsdungeons ab.", completion = "Ah, {name}. Ihr seid zurück. Euch umgibt wahrlich eine Aura aus einer anderen Welt.", sourceObjectiveStatus = "unverified-source-field" }
quests[53036] = { id = 53036, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Aufruf zur Schlacht", description = "Der Lieblingsstern der Kriegsherren und Generäle beherrscht den Himmel und bringt allen Strategen Glück. Einige sagen, der Kampfstern schärft die Instinkte von Kommandanten so weit, dass es Wahrsagerei gleicht. Wenn Ihr je daran gedacht habt, Euch auf dem Schlachtfeld zu beweisen, ist jetzt der richtige Zeitpunkt dafür.", sourceObjective = "Gewinnt 4 Schlachtfeldpartien.", completion = "Ich vermute, dass Eure Schlachten gut verlaufen sind. Eigentlich ist das keine Vermutung. Ich weiß es. Ich wusste es schon immer.", sourceObjectiveStatus = "unverified-source-field" }
quests[53037] = { id = 53037, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abgesandter des Krieges", description = "Wenn das Zeichen des Kriegers am Nachthimmel leuchtet, ist das Schicksal den Wagemutigen hold. Mächtige Feinde können noch größere Belohnungen erbringen. Begebt Euch tief in die Höhlen und Festungen, um Euch als würdig zu erweisen.", sourceObjective = "Schließt 4 Dungeons auf dem Schwierigkeitsgrad 'Mythisch' ab.", completion = "Gut gemacht, {name}. Ich wusste, dass Ihr es schaffen würdet.", sourceObjectiveStatus = "unverified-source-field" }
quests[53038] = { id = 53038, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Haustierchampion", description = "Dies ist eine wahrhaft ungewöhnliche Sternenkonstellation. Sie ist dafür verantwortlich, dass die kleinsten Kreaturen ungewöhnliche Fähigkeiten entwickeln. Keiner unserer Weisen kann dieses Phänomen erklären, aber für geschickte Zähmer ist dies eine perfekte Gelegenheit, ihre Fähigkeiten gegen andere auf die Probe zu stellen.", sourceObjective = "Besiegt 5 Spieler über 'Kampf finden' mit einer Gruppe aus Haustieren auf Stufe 25.", completion = "Gut gemacht, {name}. Ihr habt Mut bewiesen, alle Herausforderungen auf dem Wege bestanden und Euch über Tage hinweg den Platz erkämpft, der Euch zusteht.", sourceObjectiveStatus = "unverified-source-field" }
quests[53039] = { id = 53039, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Arena ruft", description = "Diese Sternenkonstellation ist ein düsteres Omen. Sie ruft Blutlust hervor und zwingt Krieger zur Teilnahme an tödlichen Nahkämpfen. Die Arenameister verdienen gut dieser Tage. Vermutlich wissen sie nicht einmal, warum so viele Krieger in ihren Arenen antreten wollen. Neben der fiebrigen Spannung erwarten alle, die mutig oder töricht genug sind, sich diesen Arenakämpfen zu stellen, große Belohnungen...", sourceObjective = "Gewinnt 10 Arenageplänkel.", completion = "Gut gemacht, {name}. Ich wusste, Ihr würdet es schaffen.", sourceObjectiveStatus = "unverified-source-field" }
quests[53040] = { id = 53040, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sturmrauschen" }
quests[53041] = { id = 53041, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stichproben", description = "Bronhavn ist ein großes Handelszentrum in diesem Gebiet. Selbstverständlich hat Aschenwind dort Büros und Werkstätten.\n\nSeht Euch in der Stadt um. Vielleicht könnt Ihr etwas über dieses neue Material und seine Verwendung erfahren.\n\nWenn Ihr eine Probe für uns mitbringen könnt, damit wir sie nach Boralus schicken können, wäre das umso besser.\n\nIch muss hierbleiben und jemanden im Auge behalten.", sourceObjective = "Besorgt die Chemikernotizen und eine Rohazeritprobe.", progress = "<Finn wirft Euch einen Seitenblick zu, während er versucht, möglichst lässig auszusehen.>\n\nHabt Ihr bekommen, was Ihr braucht?", completion = "Gut, die behalte ich vorläufig bei mir.\n\nIch glaube, wir haben unsere nächste Spur gefunden.", sourceObjectiveStatus = "unverified-source-field" }
quests[53042] = { id = 53042, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sturmrufer" }
quests[53043] = { id = 53043, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Missionsbericht: Das Geiernest", description = "Eure Anhänger haben Euch einen Bericht über die Mission, das Geiernest in Vol'dun einzunehmen, geschickt.\n\nDarin steht, dass die Mission erfolgreich war und die Truppen, die den Außenposten besetzt halten, Verstärkung angefordert haben.\n\nBringt den Bericht zu Hochkommandant Wyrmbann an Bord der Erlösenden Winde.", sourceObjective = "Bringt den Bericht über Euren Sieg zu Halford Wyrmbann.", progress = "Gibt es Neuigkeiten über die Mission nach Vol'dun?", completion = "Die Mission rund um das Geiernest war wohl von Erfolg gekrönt. Gut gemacht, {name}.\n\nIch werde Euch sofort entsenden, damit Ihr den Bau der Befestigungsanlagen beaufsichtigt.", sourceObjectiveStatus = "unverified-source-field" }
quests[53044] = { id = 53044, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Geiernest", description = "Die Mission, das Geiernest in Vol'dun einzunehmen, war erfolgreich. Gut gemacht.\n\nDer Außenposten ist bereit zur Übernahme.\n\nMacht Euch auf den Weg zum Geiernest und baut dort Befestigungsanlagen.\n\nEs wird als Außenposten eine entscheidende Rolle in unserer Kampagne gegen die Horde spielen.\n\nFür die Allianz!", sourceObjective = "Beansprucht das Geiernest für die Allianz.", completion = "Dieser Außenposten bietet uns einen idealen Aussichtspunkt, um die Bewegungen der Streitkräfte der Sethrak unter uns zu überwachen.", sourceObjectiveStatus = "unverified-source-field" }
quests[53045] = { id = 53045, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bestandsaufnahme am Kai", description = "Der Drescherkai ist ein florierender Umschlagplatz für Fischer und liegt Fort Daelin gegenüber auf der anderen Seite der Flussmündung.\n\nEr lag außerdem mitten auf dem Kriegspfad der Naga. Wer weiß, was da noch übrig ist.\n\nWenn Ihr dort vorbeischauen und Euch bei Steuerfrau Haken melden könntet, wäre ich Euch sehr verbunden. Ich muss mich darauf konzentrieren, die Verwundeten hier zu versorgen und mich auf den nächsten Angriff der Naga vorbereiten.", sourceObjective = "Sprecht mit Steuerfrau Haken am Drescherkai.", completion = "Ah, genau, was ich gebraucht habe. Ein frisches Paar Ohren, die ein oder zwei Geschichten lauschen können!", sourceObjectiveStatus = "unverified-source-field" }
quests[53050] = { id = 53050, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tiefer nach Kul Tiras hinein", description = "Es ist Zeit, unseren Einfluss in Kul Tiras weiter auszubauen.\n\nKehrt zur Klagelied zurück. Von dort aus werden wir die weitere Vorgehensweise planen.", sourceObjective = "Trefft Euch mit Nathanos Pestrufer auf der Klagelied im Hafen von Zandalar.", completion = "Es ist Zeit, einen weiteren Stützpunkt zu errichten, {name}. Seid Ihr bereit?", sourceObjectiveStatus = "unverified-source-field" }
quests[53052] = { id = 53052, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tiefer nach Zandalar hinein", description = "Unsere Berater haben entschieden, dass jetzt die richtige Zeit ist, um unseren Einfluss in Zandalar auszuweiten.\n\nKehrt rasch zur Erlösenden Winde zurück. Wir werden umgehend zu neuen Gestaden aufbrechen.", sourceObjective = "Trefft Euch mit Halford Wyrmbann an Bord der Erlösenden Winde im Hafen von Boralus.", completion = "Willkommen zurück, {name}. Machen wir uns an die Arbeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[53053] = { id = 53053, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zum Mugambala!", description = "Die Rastari haben sich als beeindruckende Verbündete im Kampf erwiesen und uns erreichen Berichte, die erklären, wie sie ihre Kampfkünste geschärft haben.\n\nJe'stry der Ungezähmte hat einen Kampfring am Fuß vom Mugambala errichtet, der sich bei den Kriegsvorbereitungen als nützlich erweisen könnte. Wir haben unsere Truppen losgeschickt, damit sie dieses Ausbildungsgelände nutzen. Seht, was der Oberste Kriegsfürst Volrath dabei entdeckt hat.", sourceObjective = "Sprecht mit dem Obersten Kriegsfürsten Volrath am Mugambala.", completion = "Willkommen bei der Duellantengilde, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[53054] = { id = 53054, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Duellantengilde", description = "Ich dachte mir schon, dass <ein kriegserfahrener/eine kriegserfahrene:r> {race} wie Ihr an unserer Duellantengilde interessiert sein würde. Sprecht mit einer Wache der Rastari in der Nähe, um an dem Gemetzel teilzunehmen.", sourceObjective = "Sprecht mit einer Wache der Rastari in der Nähe.", completion = "Viel Glück am Mugambala, {race}.", sourceObjectiveStatus = "unverified-source-field" }
quests[53055] = { id = 53055, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unseren Einfluss ausweiten", description = "Unsere Späher haben einen Platz für einen bedeutenden Stützpunkt in Zandalar ausgemacht.\n\nKehrt zur Erlösenden Winde zurück, damit wir Segel setzen können.", sourceObjective = "Trefft Euch mit Halford Wyrmbann an Bord der Erlösenden Winde im Hafen von Boralus.", completion = "Es ist Zeit, unseren letzten bedeutenden Stützpunkt in Zandalar zu errichten, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[53056] = { id = 53056, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unseren Einfluss ausweiten", description = "Wir haben einen Platz für einen bedeutenden Stützpunkt in Kul Tiras ausgemacht.\n\nKehrt zur Klagelied zurück, damit wir unsere neue Mission besprechen können.", sourceObjective = "Trefft Euch mit Nathanos Pestrufer auf der Klagelied im Hafen von Zandalar.", completion = "Es ist Zeit, unseren letzten bedeutenden Stützpunkt in Kul Tiras zu errichten.", sourceObjectiveStatus = "unverified-source-field" }
quests[53061] = { id = 53061, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Azeritauftrieb", description = "{name}, wir haben Informationen erhalten, die uns von einer nachhaltigen Azeritquelle berichten.\n\nWir müssen diesen wertvollen Rohstoff vor unseren Feinden von der Horde in die Hände bekommen.\n\nMeldet Euch so bald wie möglich an Bord der Erlösenden Winde, um bei der Gewinnung zu helfen.", sourceObjective = "Trefft Euch mit Halford Wyrmbann an Bord der Erlösenden Winde im Hafen von Boralus.", completion = "Wir wissen Eure Pünktlichkeit zu schätzen, {name}. Wir müssen uns beeilen.", sourceObjectiveStatus = "unverified-source-field" }
quests[53062] = { id = 53062, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Azeritauftrieb", description = "Wir haben Informationen erhalten, die uns von einer nachhaltigen Azeritquelle berichten.\n\nWir müssen uns beeilen, um diesen Rohstoff für die Horde zu sichern.\n\nMeldet Euch auf der Klagelied, um bei dieser dringenden Mission zu helfen.", sourceObjective = "Trefft Euch mit Nathanos Pestrufer auf der Klagelied im Hafen von Zandalar.", completion = "Wir dürfen keine Zeit verschwenden.", sourceObjectiveStatus = "unverified-source-field" }
quests[53063] = { id = 53063, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Mission der Einheit", description = "Ihr habt während Eurer Zeit hier in Kul Tiras viel für die Allianz getan, {name}.\n\nHeute müssen wir noch mehr von Euch erbitten. Kehrt an Bord der Erlösenden Winde zurück, sobald Ihr Gelegenheit habt, damit wir alles besprechen können.", sourceObjective = "Trefft Euch mit Halford Wyrmbann an Bord der Erlösenden Winde im Hafen von Boralus.", completion = "Ich habe noch eine wichtige Mission für Euch, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[53064] = { id = 53064, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Mission der Einheit", description = "Ihr habt während Eurer Zeit hier in Zandalar weite Reisen unternommen.\n\nEs ist Zeit für Eure nächste Mission. Meldet Euch auf der Klagelied.", sourceObjective = "Trefft Euch mit Nathanos Pestrufer auf der Klagelied im Hafen von Zandalar.", completion = "Seid Ihr bereit für Eure nächste Mission?", sourceObjectiveStatus = "unverified-source-field" }
quests[53065] = { id = 53065, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Operation: Totengräber", description = "Sylvanas hat uns eine Mission in Drustvar übertragen, wo wir unser nächstes Ziel finden werden.\n\nMeldet Euch umgehend auf der Klagelied.", sourceObjective = "Trefft Euch mit Nathanos Pestrufer auf der Klagelied im Hafen von Zandalar.", completion = "Gut. Ihr habt nicht herumgetrödelt.", sourceObjectiveStatus = "unverified-source-field" }
quests[53066] = { id = 53066, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Operation: Wasserweisheit", description = "Rexxar hat sich zurückgemeldet und hatte Neuigkeiten über einen neuen... Verbündeten.\n\nMeldet Euch auf der Klagelied für eine Einsatzbesprechung.", sourceObjective = "Trefft Euch mit Nathanos Pestrufer auf der Klagelied im Hafen von Zandalar.", completion = "Mach Euch bereit, die Segel in Richtung Sturmsangtal zu setzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[53067] = { id = 53067, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Operation: Gründler", description = "Es ist Zeit, dass Zelling der Horde seinen Wert beweist.\n\nKehrt zur Klagelied zurück. Heute segeln wir hinaus aufs offene Meer.", sourceObjective = "Trefft Euch mit Nathanos Pestrufer auf der Klagelied im Hafen von Zandalar.", completion = "Seid Ihr am Tiefseetauchen interessiert?", sourceObjectiveStatus = "unverified-source-field" }
quests[53068] = { id = 53068, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Operation: Haken und Leine", description = "Dank der Hilfe unserer neuen Verbündeten haben wir einen Plan entwickelt, um ein mächtiges Artefakt der Gezeitenwesen aus Boralus herauszuholen.\n\nIch habe für den Anfang Valentin bereits losgeschickt.\n\nMeldet Euch schleunigst auf der Klagelied.", sourceObjective = "Trefft Euch mit Nathanos Pestrufer auf der Klagelied im Hafen von Zandalar.", completion = "Ich hoffe, Ihr seid auf eine leichte Infiltration vorbereitet, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[53069] = { id = 53069, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Operation: Blutpfeil", description = "Wir haben ein Ziel von höchster Wichtigkeit in Nazmir ausgemacht.\n\nKehrt zur Erlösenden Winde für Eure Einsatzbesprechung zurück.", sourceObjective = "Trefft Euch mit Halford Wyrmbann an Bord der Erlösenden Winde im Hafen von Boralus.", completion = "Wir kehren heute in die rauen Lande Nazmirs zurück, {name}. Ich hoffe, Ihr seid vorbereitet.", sourceObjectiveStatus = "unverified-source-field" }
quests[53070] = { id = 53070, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Operation: Taschendieb", description = "Es ist Zeit, für unsere nächste Mission zusammenzukommen, obwohl Shandris und ich uns nicht einig sind, was genau diese umfassen sollte.\n\nTrefft Euch mit uns an Bord der Erlösenden Winde.", sourceObjective = "Trefft Euch mit Halford Wyrmbann an Bord der Erlösenden Winde im Hafen von Boralus.", completion = "Ich spüre es, wir sind dem Abschluss nahe, {name}. Vielleicht wird eure Anwesenheit hier helfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[53071] = { id = 53071, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Operation: Greifenklaue", description = "Der SI:7 wartet mit sehr interessanten Informationen auf.\n\nIch erbitte umgehend Eure Anwesenheit an Bord der Erlösenden Winde, um die weitere Vorgehensweise zu besprechen.", sourceObjective = "Trefft Euch mit Halford Wyrmbann an Bord der Erlösenden Winde im Hafen von Boralus.", completion = "Danke, dass Ihr so schnell hierhergekommen seid.", sourceObjectiveStatus = "unverified-source-field" }
quests[53072] = { id = 53072, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Operation: Mitten ins Herz", description = "Wir haben eine ganze Reihe wichtiger Ziele ausgeschaltet, {name}. Alles dank Eurer Hilfe.\n\nEs wird Zeit, einen Schlag direkt ins Herz des Zandalariimperiums zu führen.\n\nMeldet Euch an Bord der Erlösenden Winde, so bald Ihr könnt. Wir werden dort beginnen.", sourceObjective = "Trefft Euch mit Halford Wyrmbann an Bord der Erlösenden Winde im Hafen von Boralus.", completion = "Wir müssen jetzt wirklich alles geben.", sourceObjectiveStatus = "unverified-source-field" }
quests[53073] = { id = 53073, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Untersuchung am Hakenkap", description = "Ich bin sicher, dass Ihr den andauernden Kampflärm vom Hakenkap her gehört habt.\n\nWir haben unsere Späher hingeschickt, um herauszufinden, warum die Kämpfe nie enden wollen, und haben dort ganz unerwartet einen Übungsplatz entdeckt.\n\nDaniel Poll am Hakenkap betreibt dort eine Art Kampfzirkel in der Nähe des Handelswindmarkts. Sucht Großmarschall Tremblade in unserer Kommandozentrale auf und findet heraus, was wir in Erfahrung gebracht haben!", sourceObjective = "Sprecht mit Großmarschall Tremblade am Hakenkap.", completion = "Ihr habt also die Duellantengilde gefunden, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[53074] = { id = 53074, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verstärkung", description = "Die Rohstoffe, die Ihr sammelt, können dazu verwendet werden, neue Truppen für die Kriegsanstrengungen zu rekrutieren.\n\nKehrt regelmäßig zu mir zurück, um neue Rekrutierungsbefehle für Eure Missionen auszustellen.\n\nWenn Ihr Rohstoffe zur Verfügung habt, solltet Ihr sie jetzt verwenden, um Euren ersten Rekrutierungsbefehl auszustellen.\n\nDie Kriegsanstrengungen sind in vollem Gange. Wir brauchen frische Rekruten.", sourceObjective = "Sprecht mit Mathias Shaw, um einen Rekrutierungsbefehl auszustellen.", completion = "Ausgezeichnet. Eure neuen Rekruten werden für Missionen verfügbar sein, sobald sie ihre Ausbildung abgeschlossen haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[53075] = { id = 53075, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Duellantengilde", description = "Ich dachte mir schon, dass <ein kriegserfahrener/eine kriegserfahrene:r> {race} wie Ihr interessiert daran wäre, in der Duellantengilde an <seinen/ihren:r> Kampfkünsten zu feilen. Sprecht mit einem Rausschmeißer in der Nähe, um an dem Gemetzel teilzunehmen.", sourceObjective = "Sprecht mit einem Rausschmeißer in der Nähe.", completion = "Viel Glück in der Duellantengilde, {race}.", sourceObjectiveStatus = "unverified-source-field" }
quests[53076] = { id = 53076, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kernschmelze in der Gießerei" }
quests[53078] = { id = 53078, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schätze der Gezeiten", sourceObjective = "Plündert 8 gestrandete Versorgungsgüter im Klagenden Priel.", sourceObjectiveStatus = "unverified-source-field" }
quests[53079] = { id = 53079, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verstärkung", description = "Die Rohstoffe, die Ihr sammelt, können dazu verwendet werden, neue Truppen für die Kriegsanstrengungen zu rekrutieren.\n\nKehrt regelmäßig zu mir zurück, um neue Rekrutierungsbefehle für Eure Missionen auszustellen.\n\nWenn Ihr Rohstoffe zur Verfügung habt, solltet Ihr sie jetzt verwenden, um Euren ersten Rekrutierungsbefehl auszustellen.\n\nDie Kriegsanstrengungen sind in vollem Gange. Wir brauchen frische Rekruten.", sourceObjective = "Sprecht mit Garona der Halborcin, um einen Rekrutierungsbefehl auszustellen.", completion = "Gut. Eure neuen Rekruten werden für Missionen verfügbar sein, sobald sie ihre Ausbildung abgeschlossen haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[53081] = { id = 53081, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Missionsbericht: Ersatzteile", description = "Eure Anhänger haben einen Bericht über die Sammelmission von Bergungsgut für die Steinfaustwache übersandt.\n\nDarin wird erklärt, dass die Mission erfolgreich war und dass die benötigten Materialien gesammelt werden konnten.\n\nBringt den Bericht zu Nathanos Pestrufer an Bord der Klagelied.", sourceObjective = "Bringt den Bericht über Euren Sieg zu Nathanos Pestrufer.", progress = "Gibt es Neuigkeiten über die Mission bei der Steinfaustwache?", completion = "Die Mission, Vorräte für die Steinfaustwache zu sammeln, scheint ein Erfolg gewesen zu sein. Gut gemacht, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[53082] = { id = 53082, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ersatzteile", description = "Ein Ingenieur wurde in der Steinfaustwache stationiert, um eine Verschrottungsmaschine zu konstruieren.\n\nDie Mission zur Bergung von Material für die Maschine war dank Eurer Führung ein voller Erfolg.\n\nMacht Euch auf den Weg zur Steinfaustwache im Tiragardesund und trefft Euch mit Grizvek Kolbenhub. Er hat den Ausbau des Außenpostens überwacht.", sourceObjective = "Sprecht mit Grizvek Kolbenhub.", completion = "Diese Maschine zerlegt einfach alles! Los, probiert es nur!", sourceObjectiveStatus = "unverified-source-field" }
quests[53095] = { id = 53095, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Hoffnungsschimmer", description = "Champion, ich brauche Eure Hilfe!\n\nWir müssen Darnassus evakuieren, bevor es in Schutt und Asche liegt! Viele der Gebäude in der Stadt sind bereits in Brand geraten. Löscht die Flammen und rettet die gefangenen Zivilisten, die sich noch dort befinden!\n\nBitte, tut alles, was Ihr könnt... Wir müssen so viele Leben retten wie möglich.", sourceObjective = "Evakuiert Darnassus.", sourceObjectiveStatus = "unverified-source-field" }
quests[53096] = { id = 53096, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Short-Supply Reward" }
quests[53097] = { id = 53097, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verzweifelte Waschungen", description = "Ihr kehrt zurück. Das ist überraschend. Vielleicht gibt es doch noch Hoffnung.\n\nOb Sieg oder Niederlage, Ihr tragt die Bürde dieses Orts. Sie lastet auf Euren Schultern wie ein Umhang. Ich sehe, dass Ihr Mühe habt, sie zu tragen.\n\nEs gibt womöglich einen Weg, diese Bürde abzulegen. Ein Altar im Nordwesten. Er wurde von Gezeitenwesen erbaut, die danach strebten, die Verderbnis hinwegzuspülen.\n\nBietet Euch dem Götzen an. Er wird einen Preis fordern, wie alles seinen Preis hat. Aber mit seiner Hilfe könnt Ihr vielleicht dem Abgrund entfliehen.", sourceObjective = "Untersucht das läuternde Bildnis.", completion = "Euer Geist hat den Wahnsinn abgewiesen und ihn durch Entschlossenheit ersetzt. Vorläufig.", sourceObjectiveStatus = "unverified-source-field" }
quests[53098] = { id = 53098, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Shandris Mondfeder", sourceObjective = "Champion, es war mir eine Ehre, an Eurer Seite zu kämpfen. Unser Kampf gegen die Horde ist noch längst nicht vorbei.\n\nSolltet Ihr je meine Hilfe benötigen, ruft einfach und ich werde zur Stelle sein. Wir werden Sylvanas nur aufhalten können, wenn wir zusammenarbeiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[53099] = { id = 53099, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Körnchen kosmischer Wahrheit", description = "Wir stehen am Rande des Abgrunds, Ihr und ich. Der letzte Akt hängt drohend über uns und wirft einen schrecklichen Schatten voraus.\n\nWir loteten vieles aus und suchten nach dem Wissen der Welt. Dann sind wir noch tiefer vorgedrungen, bis unser Schicksal unausweichlich war. Einigen wurde der Verstand geraubt und meine Kameraden rannten schreiend in die Nacht hinaus. Wir sind alle verloren und diesem furchtbaren Ding ausgeliefert...\n\nUnd nun winkt die missgestaltete Syzygie. Vervollständigt das Ritual und führt das Ende herbei.", sourceObjective = "Bezwingt den Aszendentenalptraum.", completion = "Sieg... töricht und bedeutungslos.", sourceObjectiveStatus = "unverified-source-field" }
quests[53100] = { id = 53100, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Missionsbericht: Tötung der Riesen", description = "Eure Anhänger haben Euch einen Bericht über die Mission an der Steinhauerwacht geschickt.\n\nDarin wird erklärt, dass die Mission ein Erfolg war und dass einer der Ettins gefangen gehalten wird.\n\nBringt den Bericht zu Nathanos Pestrufer an Bord der Klagelied.", sourceObjective = "Bringt den Bericht über Euren Sieg zu Nathanos Pestrufer.", progress = "Gibt es Neuigkeiten über die Mission bei der Steinhauerwacht?", completion = "Die Mission an der Steinhauerwacht scheint ein Erfolg gewesen zu sein. Gut gemacht, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[53101] = { id = 53101, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ettikette", description = "Ein Ettin wurde von unseren Truppen an der Steinhauerwacht eingefangen.\n\nOffenbar wird die Kreatur als Lasttier für die Horde ausgebildet.\n\nMacht Euch auf den Weg zur Steinhauerwacht im Sturmsangtal und trefft Euch mit Wyna Brisenhorn. Sie hat den Ettin abgerichtet, damit er ihr gehorcht.", sourceObjective = "Sprecht mit Wyna Brisenhorn.", completion = "Ettins sind gar nicht so schwer abzurichten, wie Ihr vielleicht glaubt. Nur zu, macht einen Ausritt auf Donk. Das wird schon, er ist recht friedlich!", sourceObjectiveStatus = "unverified-source-field" }
quests[53102] = { id = 53102, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Missionsbericht: Der Ruf der Natur", description = "Eure Anhänger haben Euch einen Bericht über die Mission an der Flinkwindstation geschickt.\n\nDarin wird erklärt, dass die Mission ein Erfolg war und die Druiden dort anschließend ihr Druidenwissen mehren konnten.\n\nBringt den Bericht zu Nathanos Pestrufer an Bord der Klagelied.", sourceObjective = "Bringt den Bericht über Euren Sieg zu Nathanos Pestrufer.", progress = "Gibt es Neuigkeiten über die Mission bei der Flinkwindstation?", completion = "Die Mission an der Flinkwindstation scheint ein Erfolg gewesen zu sein. Gut gemacht, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[53103] = { id = 53103, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weidenmagie", description = "Scheinbar haben die Druiden an der Flinkwindstation viel aus den uralten Drustritualen gelernt, die Ihr wiederentdeckt habt.\n\nDie Druiden können nun verbesserte Dienste am Außenposten anbieten.\n\nMacht Euch auf den Weg zur Flinkwindstation in Drustvar und seht, was sie zu bieten haben.", sourceObjective = "Sprecht mit Toska Adlerhorn.", completion = "Wir haben viel von der einzigartigen Naturmagie der Drust gelernt. Jetzt können wir Euch einige ganz spezielle Segen anbieten, {name}.\n\nDiese Segen der Natur werden Euch bei jedem Eurer Besuche zur Verfügung stehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[53105] = { id = 53105, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fehlbesetzter Glaube", description = "Die Luft ist faulig von der Verderbnis. Das muss sich ändern.\n\nDie Gezeitenweisen waren Dummköpfe, und ich war töricht genug, ihnen zu vertrauen. Zu glauben, dass ihr Gott Wunder vollbringen und uns von unserer Dummheit erlösen würde. Dennoch haben ihre Methoden dabei geholfen, die faulige Präsenz von diesen Klippen zu vertreiben.\n\nEin einfacher Rauchschwenker gefüllt mit ausgewählten Pulvern und Ölen. Die Dämpfe haben die Wirkung, dass der Nebel sich auflöst, und sei es nur für eine Weile.\n\nVielleicht haben ihre wirkungslosen Gesten nun doch endlich einen Zweck.", sourceObjective = "Verwendet den reinigenden Weihrauchschwenker, um 13 Quellen der Verderbnis zu läutern.", completion = "Der Gestank ist fort. Vielleicht kann sich die Realität wieder an diesem Ort ansiedeln.", sourceObjectiveStatus = "unverified-source-field" }
quests[53106] = { id = 53106, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schwingen lassen" }
quests[53107] = { id = 53107, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Plünderung und Vorräte" }
quests[53108] = { id = 53108, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bildersturm" }
quests[53109] = { id = 53109, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Haus Kronsteig", description = "Ihr habt viel für meine Heimat und die Leute von Drustvar getan.\n\nSagt Euren Verbündeten, dass das Haus Kronsteig in Kürze nach Boralus zurückkehren wird.", sourceObjective = "Kehrt zu Taelia im Büro des Hafenmeisters in Boralus zurück.", completion = "Ich kann die ganzen Vorfälle in Drustvar kaum glauben!\n\nIch bin froh, dass das Haus Kronsteig zurückkehren wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[53110] = { id = 53110, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Oberste Dornsprecher", description = "Mein Lehrer, Ulfar der Oberste Dornsprecher, muss erfahren, was hier vor sich geht.\n\nIch kann hier noch nicht weg. Es gibt zu viele Verwundete und wir müssen uns noch um die letzten verbliebenen Konstrukte kümmern.\n\nIhr habt Euch bereits als vertrauenswürdig erwiesen, <mein Freund/meine Liebe>. Bringt bitte ein paar dieser Runenmachtkerne für mich zu Ulfar.\n\nArthur wird Euch an der Spitze des Pfades zu Ulfars Höhle erwarten.", sourceObjective = "Bringt die Runenmachtkerne zu Ulfar.", progress = "Was habt Ihr denn da, Festländer?", completion = "Was habt Ihr denn da, Festländer? Ah, ich verstehe, meine Schüler haben es mit stärkeren Bedrohungen zu tun bekommen, als erwartet.\n\nDanke, dass Ihr ihnen geholfen habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[53112] = { id = 53112, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Träne Azeroths", progress = "Was habt Ihr denn da?", completion = "Meine liebe Schmiede! Also das ist... etwas wirklich Besonderes! Ein Splitter konzentrierter Agonie... das Form gewordene Leid unserer Welt. Es schmerzt mich, ihn nur anzusehen.\n\nAber diesem Splitter wohnt nicht nur Traurigkeit, sondern auch Macht inne. Wir können seine Energie nutzen, um die Wunde zu heilen. Und vielleicht sogar, um Azeroth etwas Trost zukommen zu lassen.\n\nDanke, dass Ihr mir die Träne gebracht habt, {name}." }
quests[53113] = { id = 53113, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schimmernde Muschel", progress = "Hallo! Kann ich Euch helfen?", completion = "Was ist das? Oh! Die ist ja hübsch! So eine Muschel habe ich noch nie gesehen!\n\nDaraus könnte ich ja so viele Dinge machen. Oh, sie ist perfekt für Schmuckstücke!\n\nSie ist wirklich fantastisch. Danke!\n\n<Jena zögert einen kurzen Moment und schleckt Euch dann kurz über die Wange.>" }
quests[53114] = { id = 53114, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Goldkäfer", progress = "<Krag'was Glubschaugen wenden sich Euch zu.>", completion = "<Krag'was Augen weiten sich, als Ihr den Käfer herausholt. Bevor Ihr reagieren könnt, schnellt seine riesige, klebrige Zunge hervor und reißt ihn Euch aus der Hand. Im Nu hat er seine Beute heruntergeschluckt.>\n\n<Krag'wa lässt sich wieder auf seinen Bauch nieder, rülpst zufrieden und schließt seine Augen.>" }
quests[53115] = { id = 53115, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Inseltreibgut", progress = "Hey, Zastamann. Was bringt Ihr mir?", completion = "<Jani schnüffelt in der Luft und riecht Euren nassen Abfall.>\n\nIhr habt dem alten Jani 'n Geschenk mitgebracht! Was habt Ihr denn da? Lasst mal seh'n.\n\n<Jani beginnt, den Haufen Abfall, den Ihr mitgebracht habt, zu durchwühlen.>\n\nOh, ja, un' davon was, hmm, hmmhm, ja, oh das is' klebrig...\n\n<Jani scheint Euer Mitbringsel zu gefallen, denn er schenkt Euch keine Aufmerksamkeit mehr.>" }
quests[53116] = { id = 53116, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rostiges Hordenabzeichen", progress = "Lok'tar, Held.", completion = "Ah, ja, ich verstehe.\n\nAuch dieser Krieg wird seine Opfer fordern, Held . Dieses Abzeichen gehörte einem Mitglied der Horde, das im Kampf gefallen ist. \n\nDas ist die Natur des Krieges und dennoch muss ich an das Leid der Familie des Opfers denken.\n\nIch werde für sie tun, was ich kann. Danke, dass Ihr mir das gebracht habt." }
quests[53117] = { id = 53117, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rostiges Allianzabzeichen", progress = "Ja, Champion?", completion = "Auch dieser Krieg wird seine Verluste fordern. Es ist traurig, dass so vieles geopfert werden muss, um das zu bewahren, was uns lieb ist.\n\nDieses Abzeichen gehörte einem Soldaten der Allianz. Ich werde versuchen, herauszufinden, wer es war, und gegebenenfalls die Familie unterrichten.\n\nSagt mir bitte Bescheid, wenn Ihr noch mehr davon findet." }
quests[53118] = { id = 53118, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eingedellte Münze", progress = "Was habt Ihr zu berichten?", completion = "He, was ist das denn? So eine Münze habe ich ja schon lange nicht mehr gesehen.\n\nDie muss aus der Zeit des Zweiten Krieges stammen. Die Vorräte waren damals knapp und wir brauchten etwas, um mit den Einheimischen zu handeln. Sie haben diese Münzen verwendet und wir haben sie übernommen. \n\nDie riecht sogar noch nach Schießpulver. Ah, das waren noch Zeiten.\n\nAber was macht Ihr eigentlich noch hier? Wegtreten!" }
quests[53119] = { id = 53119, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verlorene Meeresschriftrolle", progress = "Ja? Was habt Ihr denn da?", completion = "Oh, das ist eine sehr alte Schriftrolle, sogar für ein Meeresrelikt.\n\nJene, die mit den Wellen gesprochen haben, haben schon lange vor der Zeit unserer Aufzeichnungen gelebt. Die Relikte unserer ältesten Gezeitensprecher sind auf der ganzen Welt verloren gegangen. Sie versanken in den Tiefen, mit denen sie sprachen.\n\nIch werde sie an einem sicheren Ort verwahren. Danke, dass Ihr sie mir gebracht habt." }
quests[53120] = { id = 53120, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Exotische Gewürze", progress = "Oh, hallo. Habt Ihr etwas für mich?", completion = "Oh, das ist ja großartig! So eine Gewürzmischung habe ich noch nie gesehen.\n\nDie Händler des Großen Meeres stellen ihre eigenen exotischen Gewürzmischungen her und sie sind alle einzigartig. Ich nehme gern noch weitere davon, wenn Ihr noch welche finden solltet!\n\nDiese hier riecht wirklich köstlich! Vielleicht sollte ich sie mit Fisch probieren...? Oder mit Karotten...? Hm..." }
quests[53121] = { id = 53121, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Belagerung von Boralus", sourceObjective = "Eine Schande, dass Ihr nicht dabei wart, {name}. Die Greifenreiter der Zwerge griffen uns an, aber sie hatten wohl nicht damit gerechnet, dass sich auf dem Boot so viele gut ausgebildete Kämpfer befinden.\n\nSogar Zelling hat mitgemischt!\n\nIch hab bei einem der toten Zwerge diesen Brief gefunden. Es scheint Spannungen zwischen der Führung in Kul Tiras und einem der großen Häuser, dem Haus Kronsteig, zu geben. Das ist vielleicht eine gute Gelegenheit für uns, in Boralus ein bisschen Chaos zu stiften.", sourceObjectiveStatus = "unverified-source-field" }
quests[53122] = { id = 53122, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Zeit zum Feiern", description = "Seid gegrüßt, {class}.\n\nDie Schlotternächte sind eine Zeit des Feierns und der Besinnlichkeit, obwohl es scheint, dass viele von uns vergessen haben, warum. Das Verbrennen des Weidenmanns im Besonderen ist ein Rätsel für viele außerhalb der Verlassenen.\n\nReist zu den Ruinen von Lordaeron und sprecht mit der Ruferin der Dunkelheit Yanka. Sie wird Euch mehr von der Weidenmannzeremonie erzählen.", sourceObjective = "Sprecht mit der Ruferin der Dunkelheit Yanka in den Ruinen von Lordaeron.", completion = "Die Weidenmannzeremonie ist eine ehrwürdige Tradition. Es ist schön zu sehen, dass die Horde sich uns bei den Feierlichkeiten anschließt.", sourceObjectiveStatus = "unverified-source-field" }
quests[53125] = { id = 53125, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Missionsbericht: Weidenwahnsinn", description = "Eure Anhänger haben einen Bericht über die Mission in der Schlammfischerbucht übersandt.\n\nDarin wird erklärt, dass die Mission ein Erfolg war und die Druiden dort anschließend ihr Druidenwissen mehren konnten.\n\nBringt den Bericht zu Nathanos Pestrufer an Bord der Klagelied.", sourceObjective = "Bringt den Bericht über Euren Sieg zu Nathanos Pestrufer.", progress = "Gibt es Neuigkeiten über die Mission bei der Flinkwindstation?", completion = "Die Mission zur Verteidigung der Schlammfischerbucht scheint ein Erfolg gewesen zu sein. Gut gemacht, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[53126] = { id = 53126, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Weidentotem", description = "Die Verteidigung der Schlammfischerbucht war erfolgreich. Gut gemacht, {name}.\n\nNach der Schlacht wurde ein mysteriöses Totem gefunden, das Euch bei Euren Abenteuern in Drustvar noch nützlich sein könnte.\n\nBegebt Euch zur Schlammfischerbucht in Drustvar und findet heraus, was für eine Macht dieses Totem birgt.", sourceObjective = "Sprecht mit Garn Schwarzwolf.", completion = "Dieses Totem wurde nach der Schlacht gefunden. Es scheint eine seltsame Magie auszustrahlen. Ich persönlich traue ihm nicht...", sourceObjectiveStatus = "unverified-source-field" }
quests[53127] = { id = 53127, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Klage des Lordadmirals", description = "Die Schließkiste enthält ein paar persönliche Dinge von Lordadmiral Daelin Prachtmeer. Darunter ist auch ein eingerollter Brief, der mit seegrünem Wachs versiegelt ist und das Wappen der Prachtmeers trägt. Das Pergament ist ganz brüchig und muss vorsichtig behandelt werden. Und auch die Tinte scheint im Laufe der Zeit und durch die salzige Seeluft verblasst zu sein.\n\nVielleicht kann jemand diesen Brief restaurieren und den Inhalt offenlegen.", sourceObjective = "Bringt die unleserliche Korrespondenz zu jemandem in Orgrimmar.", progress = "Was ist das?", completion = "Es gab Gerüchte, dass Daelin vor seinem Tod nach seiner Tochter gesucht hat. Wenn dieser Brief das ist, was ich glaube, haben wir hier einen der Gründe für den Krieg vor uns.", sourceObjectiveStatus = "unverified-source-field" }
quests[53128] = { id = 53128, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Klage des Lordadmirals", description = "Die Schließkiste enthält ein paar persönliche Dinge von Lordadmiral Daelin Prachtmeer. Darunter ist auch ein eingerollter Brief, der mit seegrünem Wachs versiegelt ist und das Wappen der Prachtmeers trägt. Das Pergament ist ganz brüchig und muss vorsichtig behandelt werden. Und auch die Tinte scheint im Laufe der Zeit und durch die salzige Seeluft verblasst zu sein.\n\nVielleicht kann jemand diesen Brief restaurieren und den Inhalt offenlegen.", sourceObjective = "Bringt die unleserliche Korrespondenz zu Kayla Mills in Sturmwind.", progress = "Was ist das?", completion = "Diese Schriftrolle birgt Geschichte, {name}. Wenn dieser Brief enthält, was ich denke, ist es eine traurige Geschichte.\n\nLasst mich bitte mal sehen...", sourceObjectiveStatus = "unverified-source-field" }
quests[53129] = { id = 53129, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blutige Schildwachengleve", description = "Die Gleve liegt nur wenige Zentimeter von den Fingerspitzen der Schildwache entfernt. Ihre toten Augen starren ausdruckslos in Richtung des abgebrannten Teldrassil am Horizont.\n\nVielleicht kann Euch jemand in Orgrimmar erzählen, was hier vorgefallen ist.", sourceObjective = "Bringt die blutige Schildwachengleve zu Isabella in Orgrimmar.", progress = "Ja?", completion = "Ah, ja, ich glaube, ich weiß, warum Ihr mir das gebracht habt, {name}. Setzt Euch, dann werde ich es Euch erklären.", sourceObjectiveStatus = "unverified-source-field" }
quests[53130] = { id = 53130, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blutige Schildwachengleve", description = "Die Gleve liegt nur wenige Zentimeter von den Fingerspitzen der Schildwache entfernt. Ihre toten Augen starren ausdruckslos in Richtung des abgebrannten Teldrassil am Horizont.\n\nVielleicht kann Euch jemand in Sturmwind erzählen, was hier vorgefallen ist.", sourceObjective = "Bringt die blutige Schildwachengleve zu Kayla Mills in Sturmwind.", progress = "Kann ich Euch helfen?", completion = "Ah, ich weiß schon, was los ist. Ihr habt Teldrassil gesehen. Oder zumindest das, was von davon übrig ist. Setzt Euch, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[53131] = { id = 53131, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Königsruh", sourceObjective = "Die Horde begleitet die San'layn nicht zum Spaß überallhin. Da sind jede Menge wichtige Persönlichkeiten der Horde dabei. Irgendetwas geht da vor.\n\nDas Gute bei den wichtigen Zielen der Horde sind die Unterlagen, die sie oft bei sich führen. Schaut, diese Karte habe ich bei einem der Toten gefunden. Seht Ihr den großen roten Kreis mit der Bezeichnung \"Königsruh\"? Was bedeutet \"Königsruh\"? Warum weiß die Allianz nichts davon?\n\nWir müssen das herausfinden, sobald wir wieder zurück an Land sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[53146] = { id = 53146, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Faust um Faust", description = "Die Oger der Felsfäuste setzen Arathi schon seit dem Zweiten Krieg zu. Es hört einfach nicht auf.\n\nIhr wisst, was getan werden muss.", sourceObjective = "Tötet 20 Oger der Felsfäuste im Arathihochland.", completion = "Ihr habt den Klan etwas ausdünnen können? Gut gemacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[53148] = { id = 53148, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Faust um Faust", description = "Wenn sich die Oger der Felsfäuste nicht der Horde anschließen wollen, gibt es keinen Platz für sie in Arathi.\n\nIhr wisst, was getan werden muss.", sourceObjective = "Tötet 20 Oger der Felsfäuste im Arathihochland.", completion = "Ihr habt den Klan etwas ausdünnen können? Gut gemacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[53149] = { id = 53149, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bleichborken beseitigen", description = "Die Geschichte des Bleichborkenklans im Hochland von Arathi ist lang und blutig.\n\nZeigt ihnen, wie viel blutiger sie noch werden kann.", sourceObjective = "Tötet 20 Trolle der Bleichborken im Arathihochland.", completion = "Habt Ihr die Trolle besiegt? Gut gemacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[53150] = { id = 53150, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bleichborken beseitigen", description = "Der blutrünstige Bleichborkenklan hat sich immer geweigert, der Horde beizutreten... Und jetzt, wo die Horde Arathi hält, werden wir erreichen, wozu die Allianz nicht imstande war.\n\nVertreibt die Waldtrolle aus dem Hochland.", sourceObjective = "Tötet 20 Trolle der Bleichborken im Arathihochland.", completion = "Habt Ihr die Trolle besiegt? Gut gemacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[53151] = { id = 53151, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Missionsbericht: Der Wolfsbau", description = "Eure Anhänger haben Euch einen Bericht über die Mission am Wolfsbau geschickt.\n\nDarin wird erklärt, dass die Mission ein Erfolg war und ein Rudel Terrorwölfe jetzt den Außenposten bewacht.\n\nBringt den Bericht zu Nathanos Pestrufer an Bord der Klagelied.", sourceObjective = "Bringt Euren Missionsbericht zu Nathanos Pestrufer.", progress = "Gibt es Neuigkeiten über die Mission zum Tiragardesund?", completion = "Die Mission am Wolfsbau im Tiragardesund scheint ein Erfolg gewesen zu sein. Gut gemacht, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[53152] = { id = 53152, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wölfe für den Bau", description = "Die Mission am Wolfsbau im Tiragardesund war offensichtlich ein Erfolg. Gut gemacht, {name}.\n\nEin Rudel Terrorwölfe patrouilliert jetzt in der Gegend um den Außenposten.\n\nReist zum Wolfsbau und sorgt dafür, dass die Ausbildung der Wölfe unseren Standards entspricht.", sourceObjective = "Sprecht mit Mukkral Schwarzader.", completion = "Throm-Ka, {name}. Rexxar hat ein prächtiges Rudel Wölfe gezähmt. Sie werden am Außenposten gute Dienste leisten!", sourceObjectiveStatus = "unverified-source-field" }
quests[53153] = { id = 53153, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tod den Entweihten", description = "Selbst nach der Zerstörung von Unterstadt kämpfen die Entweihten immer noch gegen unsere Präsenz im Arathihochland.\n\nDas Farmland von Go'Shek wird wieder zur Allianz gehören. Geht und besiegt die Verlassenen.", sourceObjective = "Tötet 20 Entweihte auf Go'Sheks Hof.", completion = "Ihr habt sie vertrieben? Gut gemacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[53154] = { id = 53154, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Bund wird verlieren", description = "Selbst nach dem Fall von Burg Stromgarde setzt der Bund von Arathor seinen Einsatz im Hochland fort.\n\nDas nördliche Farmland wird zur Horde gehören. Geht und vernichtet diese Menschen.", sourceObjective = "Tötet 20 Mitglieder des Bunds von Arathor auf dem Bauernhof der Dabyries.", completion = "Ihr habt sie vertrieben? Gut gemacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[53155] = { id = 53155, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gekerbte Münze", description = "<Diese alte, abgewetzte Münze ist offensichtlich schon durch viele Hände gegangen. Die Münze weist eine ungewöhnliche Gestaltung auf und die Kanten sind ganz rostig von den vielen Jahren an der salzigen Luft des Großen Meeres.\n\nIhr habt schon einige dieser Münzen auf der ganzen Insel gesehen. Sie scheinen häufig Gebrauch zu finden.>", sourceObjective = "Bringt die gekerbte Münze zu Mili Wanderbräu im Jadewald.\n\nBereitgestellter Gegenstand:", completion = "Hallo. Seid Ihr hier, um unsere neuen Gebräue zu probieren?\n\nEine Münze? Oh, ja... So eine habe ich schon einmal gesehen. Die Inselstämme verwenden sie.\n\nManchmal besuchen sie uns und kaufen Vorräte. Sie führen ein ganz anderes Leben als wir... reisen ständig von Ort zu Ort und lassen sich nie wirklich nieder.\n\nWenn eine Gruppe ihre Zelte abbricht, um zu einer neuen Insel zu ziehen, ist es durchaus üblich, dass ein anderer Stamm den frei gewordenen Platz einnimmt. Tja, und so geht das bei denen eben immerzu weiter.\n\nAber da Ihr schon mal hier seid... Wir fischen immer wieder diese seltsamen Edelsteine aus dem Wasser. Könnt Ihr die vielleicht gebrauchen?", sourceObjectiveStatus = "unverified-source-field" }
quests[53159] = { id = 53159, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spenden für das Arathihochland: Raues Leder", description = "Es ist an der Zeit, dass wir die Konkurrenz auslöschen, meint Ihr nicht? Mit Eurer Hilfe können wir sicherstellen, dass unsere Verbündeten die benötigten Waren und Rüstungsteile bekommen, um sich auf die anstehende Schlacht vorzubereiten.\n\nSorgen wir dafür, dass unsere Verbündeten gut vorbereitet sind.", sourceObjective = "Spendet 60 Teile raues Leder für Charlane im Hafen von Boralus.", progress = "Falls Ihr auf Eurer Jagd noch mehr Leder finden solltet, wisst Ihr ja, wo Ihr mich findet.", completion = "Eine ansehnliche Gabe. Vielen Dank.", sourceObjectiveStatus = "unverified-source-field" }
quests[53160] = { id = 53160, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Uralter Kryptaschlüssel", description = "<Das magische Gerät von den Mogueindringlingen auf der Insel birgt keine Energie mehr.\n\nIhr erinnert Euch an ähnliche Geräte, mit denen die uralte Titanenmaschinerie in den Mogutresoren von Pandaria aktiviert wurde.\n\nDiese Ausgabe hier strahlt eine unheilvolle Präsenz aus.\n\nVielleicht wissen die Lehrensucher mehr über dieses Gerät.>", sourceObjective = "Bringt den Schlüssel zu Lehrensucher Cho im Tal der Ewigen Blüten.\n\nBereitgestellter Gegenstand:", completion = "Oh, hallo mein Freund. Wir haben hier nicht mehr viele Besucher. Es ist schön, Euch zu sehen. \n\nWas habt Ihr denn da?\n\nAh ja, ich sehe schon... Ein seltenes Gerät der Mogu. So eines haben wir vor vielen Jahren schon einmal gesehen.\n\nIm Zeitalter der Hundert Könige entdeckten die Mogu die Nekromantie. Mächtige Nekrofürsten der Mogu herrschten aus Krypten tief unter der Oberfläche über ihre Stämme.\n\nViele dieser Krypten gibt es noch heute. Sie wurden entweder ausgegraben oder von der Wunde der Welt erweckt. Welche es sind, kann ich Euch aber nicht sagen.\n\nOh, und ich habe da auch noch etwas für Euch. Hier, bitte.", sourceObjectiveStatus = "unverified-source-field" }
quests[53161] = { id = 53161, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ring der Riffe", description = "<Ein feiner Nebel umweht diesen Ring, als ob er ihn liebkosen wolle.\n\nDieses Objekt in der Hand zu halten, verleiht Euch im tiefsten Innern Eurer Seele ein ungutes Gefühl. Es fühlt sich an, als ob unsichtbare, eisige Hände aus dem Reich der Toten an Euch zerren würden.\n\nDieses Objekt birgt ganz klar die Macht von Helya.\n\nIhr solltet den Valarjar davon erzählen.>", sourceObjective = "Löst das Rätsel.\n\nBereitgestellter Gegenstand:", completion = "Ein weiterer Ring? Hmpf. Ja, die kriegen wir in letzter Zeit öfter zu sehen.\n\n<Valdemar schneidet eine Grimasse.>\n\nHelya wird mächtiger.\n\nÜberrascht Euch das etwa, kleine Kreatur? Habt Ihr etwa geglaubt, sie sei besiegt?\n\n<Valdemar lacht laut auf.>\n\nIhr könnt den Tod nicht töten!\n\nAber danke, dass Ihr mich heute zum Lachen gebracht habt.\n\nOdyn hat von Eurer Azeritsuche gehört und wir haben so viel zusammengetragen, wie wir konnten. \n\nHier, es gehört Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[53162] = { id = 53162, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Sünden des Syndikats", description = "Als wären die Entweihten nicht schon schlimm genug, fallen immer noch Agenten des Syndikats aus dem Alteracgebirge ein und vertreiben die ehrlichen Bauern der Allianz.\n\nBestraft sie.", sourceObjective = "Tötet 20 Mitglieder des Syndikats auf dem Bauernhof der Dabyries.", completion = "Ihr habt das Syndikat zurück ins Alteracgebirge getrieben? Gut gemacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[53163] = { id = 53163, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trinkhorn der Blutgischt", description = "<Ein großes Trinkhorn von einem Vrykul der Blutgischt.\n\nDank seiner robusten Machart konnte es die vielen Jahre auf dem Großen Meer überstehen.\n\nAls Ihr das Horn haltet, müsst Ihr daran denken, wie begierig die Vrykul hinter dem Azerit her waren. Aber wozu?\n\nVielleicht wissen die anderen Vrykulstämme mehr über die Blutgischt und ihre Pläne.>", sourceObjective = "Bringt das Horn zum weisen Vydhar.\n\nBereitgestellter Gegenstand:", completion = "<Vydhars Blätter erzittern, als Ihr Euch ihm nähert.>\n\nIch spüre eine interessante Geschichte auf mich zukommen. Ihr seid natürlich hier, weil Ihr Antworten auf Eure Fragen zur Blutgischt sucht.\n\nEs gibt im Großen Meer eine Flotte, von der es heißt, sie umfasse Tausende von Schiffen. Ihr Anführer soll der größte Pirat sein, den es jemals gab: Jorun, die Blutgischt.\n\nEr verließ uns vor langer Zeit, um sein Glück auf See zu finden. Er lebt nur für das Plündern und weilt nie sonderlich lange am selben Ort.\n\nWer weiß, vielleicht begegnet Ihr ihm eines Tages ja selbst.\n\nDieser Alte dankt Euch jedenfalls für Euren Besuch. Nehmt diese Mineralien von meinen Wurzeln.", sourceObjectiveStatus = "unverified-source-field" }
quests[53164] = { id = 53164, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schallstein", description = "<Der Stein vibriert, wenn man ihn berührt. Die Schwingung durchläuft Euren Körper und Ihr fühlt Euch erfrischt.\n\nVermutlich verwenden die Mantis diese Steine, um die großen Entfernungen über das Meer zu bewältigen.\n\nEs war seltsam, den Mantis auf der Insel zu begegnen. Der Tod von Shek'zeer war ein harter Schlag für sie. Eigentlich sollten sie jetzt nicht ausschwärmen.\n\nDie Einwohner von Pandaria dürften mehr darüber wissen.>", sourceObjective = "Zeigt den Stein Bewacherkommandant Qipan in der Tonlongsteppe.\n\nBereitgestellter Gegenstand:", completion = "Ja? Was gibt's denn? Wie Ihr sehen könnt, haben wir hier alle Hände voll zu tun.\n\nAha, wie ich sehe, seid auch Ihr dem Mantisschwarm begegnet.\n\nUnsere Befürchtungen haben sich bewahrheitet: Die neue Kaiserin ist geschlüpft. Prinzessin Zara, nein, jetzt Großkaiserin Shek'zara ist da.\n\nSie ist genauso hitzköpfig und impulsiv wie alle anderen Mantisköniginnen, und sie hat den Großteil ihrer Streitkräfte für die Azeritsuche mobilisiert.\n\nDen Grund dafür kennen wir nicht.\n\n<Qipan zerquetscht ein Insekt zwischen den Fingern.>\n\nAber es gefällt uns nicht.\n\nHier, dieses Azerit haben wir ihren Toten abgenommen. Nehmt es.", sourceObjectiveStatus = "unverified-source-field" }
quests[53165] = { id = 53165, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stopp dem Antiquitätendiebstahl" }
quests[53167] = { id = 53167, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fellumhang der Eishauer", description = "<Der Pelz dieses Umhangs ist alt und abgewetzt, aber er hält immer noch warm. Er hat schon viele Jahre in den harten, unwirtlichen Blizzards des Nordens überdauert.\n\nDer Stamm der Eishauer wurde bis jetzt noch nicht in Azeroth gesehen. Vielleicht weiß jemand in Nordend mehr darüber.>", sourceObjective = "Zeigt den Pelz Tua'kea in der Drachenöde.\n\nBereitgestellter Gegenstand:", completion = "Hallo, mein Freund. Ihr habt einen sehr eigenartigen Fischgeruch an Euch. Wo seid Ihr denn gewesen, wenn das keine zu persönliche Frage ist? Ach, es ist eigentlich auch egal. Womit kann ich Euch behilflich sein?\n\nAch ja, die Eishauer... Die wahrlich seltsame Geschichte eines kleinen Stammes.\n\nEr widerstand den Versprechen des Lichkönigs und zog stattdessen auf riesigen Kanus los, um anderswo sein Heil zu suchen.\n\nDoch stattdessen fand er nichts als Not und Elend. In seinen düsteren Zeiten wandte er sich der Nekromantie zu und konnte so knapp überleben... wenn man es so nennen mag. Eine traurige Geschichte.\n\nOh! Ich habe das hier heute Morgen geangelt. Es gehört Euch, wenn Ihr wollt.", sourceObjectiveStatus = "unverified-source-field" }
quests[53168] = { id = 53168, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Magisches Fernrohr", description = "<Mit diesem Fernrohr könnt Ihr Dinge in weiter Entfernung erkennen, aber wenn man zu lange hindurchschaut, bekommt man Kopfschmerzen.\n\nDie Linse scheint speziell für die Sehstärke eines anderen gefertigt zu sein.\n\nDie aufwendige Ausgestaltung des Fernrohrs könnte darauf hinweisen, dass man dafür einen schönen Finderlohn erhalten würde.>", sourceObjective = "Bringt das Fernrohr zurück.\n\nBereitgestellter Gegenstand:", completion = "Na was habt Ihr denn da? Oh, oh oh OH, was ist das?!\n\nMein Fernrohr!\n\nAch, Schätzchen, ich hätte nie gedacht, dass ich dich noch einmal wiedersehen würde. Wisst Ihr überhaupt, wie teuer das Ding war? Die Optik ist eine Spezialanfertigung... Wegen meines rechten Auges, wisst Ihr?\n\nIhr habt es doch nicht benutzt, oder?\n\nHört mal, mir kommen ja nicht so leicht die Tränen, aber diesmal vielleicht doch. Das Ding ist mein Ein und Alles.\n\nHier, mein gesamtes Azerit gehört Euch. Das... ist eine Menge wert... Uff! Das tut weh. Aber nehmt es nur... Na los, macht schon. Das geht so in Ordnung.", sourceObjectiveStatus = "unverified-source-field" }
quests[53169] = { id = 53169, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elementarkern", description = "<Ein ausgebrannter Kern von den Elementaren, denen Ihr begegnet seid.\n\nWenn Ihr Euch darauf konzentriert, spürt Ihr, dass tief in seinem Inneren noch etwas Elementarenergie enthalten ist.\n\nSie waren ganz eindeutig hinter dem Azerit her. Aber warum?\n\nVielleicht ist es an der Zeit, einen ausstehenden Gefallen einzufordern.>", sourceObjective = "Bringt den Kern zu Fürst Hydraxis in Azshara.\n\nBereitgestellter Gegenstand:", completion = "Ja? Mit Feuerbekämpfung habe ich nichts mehr zu tun.\n\nOh, Ihr habt Fragen zu den Elementarebenen? Sie sind im Moment ziemlich in Aufruhr. Die Elemente sind zwar immer temperamentvoll, aber die Lage ist nun wirklich außer Kontrolle geraten.\n\nDie Anwesenheit dieses Azerits hat in den niederen Fürsten den brennenden Drang entfacht, die aktuellen Fürsten zu stürzen und ihre jeweilige Ebene für sich zu beanspruchen.\n\nSie alle betrachten dieses neue Element als ein Zeichen elementarer Wiedergeburt.\n\nAber ich sehe das anders. Ich will ja nicht einmal die Edelsteine, die ich hier habe. Bitte nehmt sie.", sourceObjectiveStatus = "unverified-source-field" }
quests[53170] = { id = 53170, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unversehrte schwarze Schuppe", description = "<Eine gänzlich makellose schwarze Schuppe von den Drachen, denen Ihr kürzlich begegnet seid.\n\nDer schwarze Drachenschwarm galt nach dem Tod von Todesschwinge und Furorions Aufstieg zur Macht im Grunde als ausgelöscht.\n\nUnd doch weist die Größe der Schuppe auf einen jüngeren Drachen hin.\n\nEs gibt eine Person, einen Drachen, der garantiert davon würde erfahren wollen... aber wo IST Furorion?\n\nIhr vermutet, dass er an einem vertrauten Ort sein muss, der befestigt und verlassen ist.>", sourceObjective = "Versucht, Furorion im Schwarzfels zu finden.\n\nBereitgestellter Gegenstand:", completion = "Hallo. Man hat Euch schon angekündigt. Seid doch so gut und gebt mir die Schuppe.\n\nNatürlich sollt Ihr für Eure Mühen entschädigt werden.\n\nZunächst einmal in Form von Informationen. Habt Ihr schon von den Dracheninseln gehört? Diese Frage können nur wenige bejahen, und noch weniger sind schon einmal dort gewesen.\n\nWir haben keine weiteren Verwandten des Gebieters gefunden... die sich in Sachen Informationen entgegenkommend zeigen würden.\n\nSolltet Ihr auf Euren Reisen weitere Entdeckungen machen, erwarten wir Euren Besuch, den wir natürlich vergüten werden.\n\nIch möchte Euch hiermit auch noch das Azerit überreichen, das Ihr sucht. Hier, ein üppiger Batzen für Eure Mühen.\n\nAuf ein baldiges Wiedersehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[53171] = { id = 53171, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abgewetzte Zwielichtschuppe", description = "<Diese abgewetzte Schuppe eines Zwielichtdrachen hat schon viele Kämpfe gesehen.\n\nNach dem Tod von Sinestra sollten die Zwielichtdrachen eigentlich vollständig besiegt sein. Wie konnten so viele von ihnen auf der Insel sein?\n\nUnd wer führt ihren Schwarm an?>", sourceObjective = "Löst das Rätsel.\n\nBereitgestellter Gegenstand:", completion = "Psst! Zurück! Sie dürfen uns nicht sehen!\n\nWas tut Ihr hier? Wer hat Euch geschickt?\n\n<Eryna hört sich Eure Schilderung des Zwielichtangriffs an.>\n\nJa, wir wissen davon. Es sind diese verdammten Troggs. Nichts und niemand hindert sie am Graben! Sie sind tiefer und weiter vorgedrungen, als wir es für möglich gehalten hätten.\n\nAber nicht nur das: Wenn ich mich fest konzentriere, kann ich dort drinnen die Herzschläge Tausender winziger Kreaturen spüren. Wir wissen nicht, wie viele Eier es noch gibt...\n\nAch ja, da Ihr ohnehin schon hier draußen seid... Einer von ihnen hatte diese Edelsteine bei sich. Hier, sie gehören Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[53172] = { id = 53172, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geschäftsplan der Venture Co.", description = "<Ein riesiger, mit kleiner Schrift eng beschriebener Band. Sobald Ihr nur ein paar Sätze lest, verschwimmen die Buchstaben vor Euren Augen.\n\nDiese langjährigen Geschäftspläne der Venture Company sind hoch komplex und kaum nachvollziehbar.\n\nEine Sache aber ist klar: Ein Konkurrenzunternehmen würde viel Geld für diesen Folianten zahlen.>", sourceObjective = "Stellt Lizzarik in Ratschet.\n\nBereitgestellter Gegenstand:", completion = "Ja? Was habt Ihr denn da? Oh.\n\nHört mal, mein Name steht bloß deshalb da hinten auf dem Ding drauf, weil ich ein \"Investor\" bin. Ich wette auf den Erfolg oder Misserfolg von Unternehmen.\n\nDas ist alles ziemlich kompliziert, also zerbrecht Euch deswegen nicht Euren putzigen kleinen Kopf. Genau genommen habe ich nichts Falsches gemacht! Wir nutzen doch bloß vorhandene Infrastrukturen aus, um ein bisschen Gold zu machen.\n\nIst alles völlig harmlos.\n\nSchaut her, ich hab hier einen Riesenbeutel voller Azerit! Warum nehmt Ihr den nicht mit? Für mich ist der eigentlich viel zu schwer.", sourceObjectiveStatus = "unverified-source-field" }
quests[53173] = { id = 53173, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Sünden des Syndikats", description = "Als wäre der Bund von Arathor nicht schon schlimm genug, fallen immer noch Agenten des Syndikats aus dem Alteracgebirge ein und vertreiben die ehrlichen Hilfsarbeiter der Horde.\n\nBestraft sie.", sourceObjective = "Tötet 20 Mitglieder des Syndikats auf Go'Sheks Hof.", completion = "Ihr habt das Syndikat zurück ins Alteracgebirge getrieben? Gut gemacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[53174] = { id = 53174, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Murlocauge", description = "<Das Murlocauge scheint über keine magischen Eigenschaften zu verfügen, fühlt sich bei Berührung aber feuchtkalt an.\n\nIhr habt schon gesehen, dass Nagahexer solcherlei Objekte bei ihren Ritualen verwenden. Dass sie dazu aber ihren Murlocsklaven Körperteile entnehmen, ist eher ungewöhnlich.\n\nEin verstörendes Vorgehen, selbst für die Naga.>", sourceObjective = "Löst das Rätsel.\n\nBereitgestellter Gegenstand:", completion = "Oh! Hallo. Seid Ihr wegen der furchtbaren Dinge hier, die den Murlocs widerfahren?\n\nIch habe Geschichten über schreckliche magische Experimente gehört, die in den Tiefen durchgeführt werden. Ganze Murlocstämme werden dabei ausgelöscht.\n\nEs gibt sogar ein Gebiet, in dessen Nähe sie sich nicht mal mehr wagen. Das Wasser blubbert dort wie wild und die Hitze ist unerträglich. Sämtliche Fische und auch alle anderen Lebewesen sind geflohen. Was geht dort nur vor?\n\nAch, mir wurde übrigens etwas Azerit gebracht, auch wenn ich nicht weiß, warum. Wollt Ihr es vielleicht haben?\n\nDanke für Euren Besuch!", sourceObjectiveStatus = "unverified-source-field" }
quests[53175] = { id = 53175, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schatten der Kriegsfront", description = "Wir können nicht kurzsichtig all unsere Kräfte auf Zandalar konzentrieren. Der gesamte Planet ist Ziel der Heimtücke der Horde.\n\nZurzeit ist besonders das Arathihochland nahe der sagenumwobenen Zitadelle von Burg Stromgarde betroffen. Die Horde hat dort in der Nähe ein Lager errichtet und will uns dieses Gebiet abnehmen.\n\nSprecht mit Ralston Karn, dem für diese Kriegsfront verantwortlichen Rekrutierungsoffizier. <Ein guter/Eine gute:c> {class} wie Ihr ist bei ihm sicher gerne gesehen.", sourceObjective = "Meldet Euch bei Ralston Karn im Hafen von Boralus.", completion = "Ihr seid {name} von der 7. Legion?\n\nWillkommen. Wir haben schon von Euch gehört. Also, an die Arbeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[53176] = { id = 53176, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schillernder Skarabäus", description = "<Ein magisches Schmuckstück eines Zauberwirkers der Tol'vir. Es scheint die magischen Fähigkeiten seines Anwenders zu verstärken.\n\nEs ist vermutlich uralt, aber in makellosem Zustand. \n\nDie Tol'vir von Uldum wissen vielleicht mehr über das plötzliche Auftauchen der Amathet.>", sourceObjective = "Bringt den Skarabäus zu Hochkommandant Kamses in Uldum.\n\nBereitgestellter Gegenstand:", completion = "<Der Skarabäus hat Kamses' Aufmerksamkeit erregt.>\n\nWie ich sehe, habt Ihr mit den Amathet Bekanntschaft gemacht.\n\nDie Wunde in der Welt hat neue Gräber zum Vorschein gebracht, und aus einem von ihnen stiegen sie empor. \n\nSie reden kaum mit uns, denn in ihren Augen haben wir unsere heiligen Pflichten verraten. Sie glauben, dass sie als die Bediensteten der Titanen das Azerit kontrollieren sollten.\n\nNoch viel schlimmer ist aber, dass sie ihre eigenen neuen Hüter erschaffen haben, als sie erkannt hatten, dass Rajh und die anderen tot waren.\n\nSie müssen über eine aktive Schmiede verfügen.\n\nIch möchte Euch das Azerit geben, das uns noch geblieben ist. Seid vorsichtig, sie sind gefährlich.", sourceObjectiveStatus = "unverified-source-field" }
quests[53177] = { id = 53177, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kaputter Kompass", description = "<Dieser bei einem gestrandeten Piraten gefundene Kompass funktioniert nicht mehr. \n\nDem Metall und der Bauart zufolge müsste er aus Sturmwind stammen.>", sourceObjective = "Findet den Besitzer des Kompasses.\n\nBereitgestellter Gegenstand:", completion = "Hallo. Seid Ihr hier, um Kräuter zu kaufen?\n\nOh, was ist denn das? Ein Kompass? Der kommt mir sehr bekannt vor.\n\nDieser Idiot.\n\nEr hat immer anderswo sein Glück gesucht und es doch nie gefunden. Selbst hier zu Hause war er zu nichts zu gebrauchen. Wenn es um Kräuter ging, war er ein Totalausfall.\n\nWisst Ihr was? Ich bin sogar froh, dass er auf See verschollen ist. Soll er doch dortbleiben.\n\nHier, ich gebe Euch sogar seine Azeritvorräte. Das würde ihn nämlich mächtig ärgern.\n\nEndlich kann ich meinen eigenen Interessen nachgehen. Jetzt weht hier ein anderer Wind! Hmm, ob Kirsty wohl noch frei ist...", sourceObjectiveStatus = "unverified-source-field" }
quests[53178] = { id = 53178, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jagdspeer der Klingenflossen", description = "<Dieser Speer ist immer noch rasiermesserscharf, obschon er wohl schon viele Jahre bei der Jagd auf dem offenen Meer zum Einsatz kam.\n\nDer Schaft ist an mehreren Stellen gebrochen und mit den damalig verfügbaren Materialien repariert worden. Die Vielfalt der Reparaturmaterialien lässt darauf schließen, dass der Stamm der Jinyu, dem Ihr gerade erst begegnet seid, sehr viel umherreist.\n\nDie freundlichen Jinyu von Pandaria wissen vielleicht mehr über diesen seltsamen Stamm.>", sourceObjective = "Bringt den Speer zum müden Shushen in der Krasarangwildnis.\n\nBereitgestellter Gegenstand:", completion = "Ach ja, diesen Speer erkenne ich. Dann habt Ihr offenbar Bekanntschaft mit den Klingenflossen gemacht?\n\nSie sind anders als alle anderen Jinyu. Vor langer Zeit wurde dem Stammesältesten die Vision eines großen Ungeheuers gewährt. Er war so entsetzt, dass er es \"Onoho\", oder auch \"tiefer Schatten\", nannte.\n\nEr machte es zur Bestimmung seines Stammes, das Ungeheuer zu erlegen. Auf ihrer endlosen Suche reisen sie von Insel zu Insel und bleiben nie lang. Es ist faszinierend.\n\nIch danke Euch für Euren Besuch. Hier wurde etwas Azerit angespült. Seid so frei und nehmt es Euch, da wir damit wenig anfangen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[53179] = { id = 53179, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Exorzismus durchführen", description = "Selbst im Tod trachten diese Narren der Horde immer noch nach Allianzterritorium.\n\nVertreibt ihre rachsüchtigen Geister aus den Ruinen von Ar'gorok, bevor ihre Verderbnis um sich greift.", sourceObjective = "Tötet 20 rachsüchtige Geister in Ar'gorok.", completion = "Ihr habt die Ruinen von den Geistern befreit? Gut gemacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[53180] = { id = 53180, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorus'araks Panzer", description = "<Der Panzer des nerubischen Fürsten Vorus'arak sieht uralt aus.\n\nVorus'arak schien seinen Panzer nicht abwerfen zu wollen und hat offensichtlich den gleichen mit Kerben übersäten Panzer über eine lange Zeit getragen.\n\nAuf dem ganzen Panzer finden sich seltsame Inschriften. Es scheint sich um eine Art Sprache zu handeln.>", sourceObjective = "Bringt den Panzer zu Kilix dem Entwirrer in der Drachenöde.\n\nBereitgestellter Gegenstand:", completion = "Was ist das? Ein Panzer? Ja, ich sehe schon, die Schrift ist in meiner Sprache.\n\nSie beschreibt Schwarmfürst Vorus'arak, der Erzählungen über seine Reisen in sein eigenes Chitin ritzte.\n\nEr erzählt vom Krieg der Spinne und von seiner Flucht mit seiner Brut durch die Tunnel.\n\nVorus war ein mächtiger Gräber, doch selbst seine Kraft ließ nach und er war gezwungen, viele seiner eigenen Brut zu verschlingen.\n\nSchlussendlich fanden sie eine Insel und haben überlebt. Bis Ihr gekommen seid.\n\nUnsere Geschichte ist uns wichtig. Hier habt Ihr einige Edelsteine für die Zeit, die Ihr aufgewendet habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[53181] = { id = 53181, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Druidenfell", description = "<Dieses Fell steckt voller Naturmagie. Die Tiere, die Ihr auf der Insel bekämpft habt, waren offensichtlich gar keine Tiere, sondern Druiden.\n\nZumindest waren sie das vorher.\n\nWas könnte sie in solche Raserei versetzt haben?\n\nIhr wolltet sie ja gar nicht umbringen, aber sie haben Euch ja keine Wahl gelassen, oder?>", sourceObjective = "Bringt das Fell zu Loganaar auf der Mondlichtung.\n\nBereitgestellter Gegenstand:", completion = "Dieses Fell... wurde längere Zeit keinem Gestaltwandel unterzogen.\n\nIch gehe davon aus, dass Ihr einem meiner Art begegnet seid, der wild geworden war, ja? Das... würde dann Sinn ergeben.\n\nNach dem Krieg der Satyrn waren einige von uns der Ansicht, dass der einzig wahre Weg der des Rudels ist. Dass wir in unserem tiefsten Innern wilde Kreaturen seien und unsere menschlichen Gestalten nur eine Maske.\n\nSie schwangen sich als Schwarm in die Lüfte und man hat nie wieder von ihnen gehört. Bis jetzt.\n\nIch danke Euch für diese Informationen. Hier ist etwas Azerit, das ich für den Sprecher gesammelt habe.", sourceObjectiveStatus = "unverified-source-field" }
quests[53182] = { id = 53182, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Würgewurzel", description = "<Die Wurzel windet sich in Eurer Hand und versucht, sich um Euren Arm zu wickeln.\n\nDie Hüter, denen Ihr begegnet seid, müssen über gewaltige natürliche Macht verfügen, wenn die Magie ihrer Schöpfungen so lange anhält.\n\nDie Erinnerung an ihre Entschlossenheit im Kampf gegen Euch stimmt Euch plötzlich nachdenklich.\n\nWarum haben sich die Hüter der Natur nur so seltsam benommen?\n\nIrgendjemand wird die Antwort auf dieses Rätsel kennen.>", sourceObjective = "Bringt die Wurzel zu Bewahrer Remulos auf der Mondlichtung.\n\nBereitgestellter Gegenstand:", completion = "Diese Wurzel sagt mir alles, was ich über Eure Reise wissen muss: eine Insel, erfüllt vom Geist des Lebens, und Ihr habt dort Bewahrer getroffen.\n\nIch spüre, dass deren Handlungen Euch überrascht haben.\n\nNicht alle, die wir die Natur schützen, sehen Eure Art als Verbündete. Viele von meinesgleichen wollen in erster Linie das Gleichgewicht bewahren, auch wenn das Euren Tod bedeutet.\n\nIch werde es Euch nicht zum Vorwurf machen, dass Ihr Euch verteidigt habt, doch es liegt auch nicht in meiner Macht, sie zu beschwichtigen.\n\nMeine Kitze haben jedoch etwas Azerit für Euch gesammelt.", sourceObjectiveStatus = "unverified-source-field" }
quests[53183] = { id = 53183, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zuckende Masse", description = "<Das Tentakel in Eurer Hand pulsiert und windet sich, während Euer Geist von finsteren Gedanken heimgesucht wird.\n\nInsbesondere eine Vision taucht wieder und wieder auf.\n\nVor Eurem geistigen Auge seht Ihr das Bild einer vieläugigen Ziege in einem Teich schwarzen Wassers. Als Ihr Euch nähert, öffnet sie ihre Augen, und plötzlich treibt Ihr selbst in der Tiefe des Teichs und blickt nach oben zur Ziege.\n\nWährend Ihr tiefer hinab durch die Dunkelheit des eiskalten Wassers sinkt, wird alles um Euch herum schwarz.\n\nIhr steckt die Masse in die Tasche und verdrängt die finsteren Gedanken.>", sourceObjective = "Findet jemanden, der die Visionen erklären kann.\n\nBereitgestellter Gegenstand:", completion = "Bitte senkt Eure Waffe, ich will Euch nichts Böses. Das Geflüster hörte an jenem Tag auf, zu mir zu sprechen, als die Wunde aufbrach.\n\nIch möchte meine Tage damit verbringen, für meine Taten Sühne zu leisten, also kann ich Euch vielleicht helfen.\n\nIhr... Ich sehe es an Euren Augen, dass Ihr die Vision gesehen habt.\n\nDie Ziege, der Teich, Ertrinken in der eisigen Dunkelheit, sagt Euch das etwas?\n\nIch kann Euch verraten, was es bedeutet. Es heißt, dass wir uns dem Ende dieser Welt rasch nähern, mein Freund.\n\nNehmt mein Azerit, ich kann es nicht mehr gebrauchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[53184] = { id = 53184, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verwittertes Flugblatt", description = "<Dieses Schriftstück ist offensichtlich ein massenhaft produziertes Flugblatt einer Agentur, die Azerit ankauft.\n\nIhr könnt ein paar der blumigen Sätze entziffern: \"Euer Reichtum liegt im Großen Meer!\" und \"Alle werden reich! Seid Ihr dabei?\" \n\nVon den damit verbundenen Gefahren ist keine Rede.\n\nAber ganz unten auf der Seite stehen zumindest ein paar Kontaktinformationen.>", sourceObjective = "Findet den Urheber des Flugblatts.\n\nBereitgestellter Gegenstand:", completion = "Seid Ihr wegen des Flugblatts hier?\n\nWas denn, habt Ihr jemand Grüneres erwartet? Hört mal, wir brauchen schließlich alle was zu essen. Ich habe eine Familie zu Hause und der Krieg nimmt uns das ganze Essen weg.\n\nIst doch nicht mein Problem, wenn Abenteurergrünschnäbel mit Gold im Kopf in Schwierigkeiten geraten? Das hört sich eher nach Eurem Problem an.\n\nAlso, wenn Ihr mir nicht Euer Azerit verkaufen wollt, dann haut ab. Der große G mag es nicht, wenn ich zu viel quatsche.\n\nHab ich da gerade G gesagt? Vergesst das.\n\nHier, nehmt einfach etwas von meinem Azerit und haltet den Mund, ja?", sourceObjectiveStatus = "unverified-source-field" }
quests[53185] = { id = 53185, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beitrag für die Kriegsfront", description = "Eine gut ausgebildete Armee allein ist nicht alles, {name}. Wir brauchen auch Geld, Nahrung und Vorräte, um unsere Armee zu finanzieren, zu ernähren und kampfbereit zu halten.\n\nDie Allianz finanziert den größten Teil der Kriegsanstrengungen, aber für den Rest müssen hart arbeitende Bürger wie Ihr und ich aufkommen. Öffnet Euren Geldbeutel und gebt so viel Ihr könnt. Für die Allianz!", sourceObjective = "Spendet etwas als Beitrag zu den Kriegsanstrengungen. Ihr könnt, Gold, Kriegsressourcen oder hergestellte Ausrüstung beisteuern. Nur bestimmte NSCs nehmen tägliche Spenden entgegen.", completion = "Die Allianz weiß Eure Großzügigkeit zu würdigen, {name}. Damit habt Ihr uns dem Sieg ein gutes Stück näher gebracht!", sourceObjectiveStatus = "unverified-source-field" }
quests[53186] = { id = 53186, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Missionsbericht: Hinterhalt an Grimmwatts Sturz", description = "Eure Anhänger haben Euch einen Bericht über die Mission an Grimmwatts Sturz geschickt.\n\nDarin steht, dass die Mission ein Erfolg war und die angreifenden Bluttrolle bezwungen werden konnten.\n\nBringt den Bericht zu Hochkommandant Wyrmbann an Bord der Erlösenden Winde.", sourceObjective = "Bringt den Missionsbericht zu Halford Wyrmbann.", progress = "Gibt es Neuigkeiten über die Mission an Grimmwatts Sturz?", completion = "Die Mission an Grimmwatts Sturz scheint ein Erfolg gewesen zu sein. Gut gemacht, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[53187] = { id = 53187, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein unerwarteter Gast", description = "Die Mission zur Verteidigung von Grimmwatts Sturz war ein Erfolg. Gut gemacht, {name}.\n\nUnd unsere Truppen an Grimmwatts Sturz konnten nicht nur den Außenposten halten, sondern auch einen Blutkrogg gefangen nehmen. Nele Fürbittshafen ist mit der Ausbildung der Bestie beauftragt.\n\nBegebt Euch nach Grimmwatts Sturz in Nazmir und sprecht mit Nele über die Ausbildung des Kroggs.", sourceObjective = "Sprecht mit Nele Fürbittshafen.", completion = "Es ist gar nicht so schwer und dauert gar nicht so lang, einen Blutkrogg auszubilden, wie man denkt. Probiert es selbst aus und zieht mal mit \"Knolle\" hier los!", sourceObjectiveStatus = "unverified-source-field" }
quests[53188] = { id = 53188, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Frostiger Freistil" }
quests[53189] = { id = 53189, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flutsch und weg" }
quests[53190] = { id = 53190, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Exorzismus durchführen", description = "Selbst im Tod trachten diese Narren der Allianz immer noch nach Hordenterritorium.\n\nVertreibt ihre rachsüchtigen Geister aus den Ruinen von Burg Stromgarde, bevor ihre Verderbnis um sich greift.", sourceObjective = "Tötet 20 rachsüchtige Geister in Burg Stromgarde.", completion = "Ihr habt die Ruinen von den Geistern befreit? Gut gemacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[53192] = { id = 53192, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Doppelt verbannt hält besser", description = "Im ganzen Hochland reißen sich Elementare aller Art von ihren Bindungen los.\n\nSchickt sie zurück in das urzeitliche Chaos, aus dem sie gekommen sind.", sourceObjective = "Tötet 20 brennende, schäumende, rumpelnde oder donnernde Verbannte oder Wächter im Arathihochland.", completion = "Die Elementare wurden verbannt? Gut gemacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[53193] = { id = 53193, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Doppelt verbannt hält besser", description = "Im ganzen Hochland reißen sich Elementare aller Art von ihren Bindungen los.\n\nSchickt sie zurück in das urzeitliche Chaos, aus dem sie gekommen sind.", sourceObjective = "Tötet 20 brennende, schäumende, rumpelnde oder donnernde Verbannte oder Wächter im Arathihochland.", completion = "Die Elementare wurden verbannt? Gut gemacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[53194] = { id = 53194, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An die Front", description = "Ihr solltet Euch um das Arathihochland kümmern. Vorerst hat die Lage sich beruhigt, aber wenn die Kämpfe wieder aufflammen, brauchen wir Euch an der Front.\n\nYvera Dämmerschwinge betreibt ein Portal direkt nach Burg Stromgarde. Sie kann Euch helfen.", sourceObjective = "Sprecht mit Yvera Dämmerschwinge, um Euch nach Burg Stromgarde teleportieren zu lassen und sprecht dann bei Hauptmann Roderick Bräustein vor.", completion = "Krieg ist ein grausames Geschäft. So viel ist sicher.\n\nIch bin froh, dass Ihr es hergeschafft habt. Machen wir es kurz.", sourceObjectiveStatus = "unverified-source-field" }
quests[53195] = { id = 53195, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spenden für das Arathihochland: Akundas Biss", description = "Seid gegrüßt!\n\nJetzt, da unsere Kriegsanstrengungen in vollem Gange sind, bin ich Eure Ansprechpartnerin für Spenden hinsichtlich Kräuterkunde und Alchemie! Es ist mir eine Freude, Euch kennenzulernen!\n\nDann lasst uns mal sehen... Ah, ja. Sirenenpollen. Gestern Abend unterrichtete man mich, dass die Vorräte zur Neige gehen. Es wäre uns allen eine große Hilfe, wenn Ihr uns durch Euren Beitrag unterstützen könntet.", sourceObjective = "Sammelt 20 Sirenenpollen für Klara Strand im Hafen von Boralus.", progress = "Habt Ihr ein paar Kräuter für mich?", completion = "Der Geruch dieser Kräuter ist unverwechselbar.\n\nIch werde dafür sorgen, dass sie gut genutzt werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[53196] = { id = 53196, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schrubbt das!" }
quests[53197] = { id = 53197, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erkundung der Front", description = "Die Horde hat schon seit einiger Zeit nicht mehr angegriffen. Und wir auch nicht, um ehrlich zu sein. Es sollte jetzt sicher genug sein, um die Lage da draußen auszukundschaften.\n\nMeldet Euch bei unseren Vorarbeitern in der Mine und dem Sägewerk. Es wäre gut, zu wissen, dass sie nicht Reißaus genommen haben und dem Tod in die Arme gelaufen sind. Unterwegs könnt Ihr Euch außerdem nebenbei ein Bild vom Terrain verschaffen.\n\nApropos, vielleicht könntet Ihr auch bei Flugmeister Grayson Bell vorbeischauen, damit Ihr Euch die Basis unseres Feindes aus der Vogelperspektive anschauen könnt. Sie heißt \"Ar'gorok\" oder irgendsoein orcisches Kauderwelsch.", sourceObjective = "Meldet Euch bei Vorarbeiterin Tully, Bodo dem Baumstampfer und Grayson Bell.", completion = "Also wurde niemand von der Horde abgeschlachtet? Wunderbar.\n\nUnd ich bin froh, dass Ihr es heil zurückgeschafft habt, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[53198] = { id = 53198, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zurück nach Boralus", description = "Das sollte vorerst reichen. Wir melden uns, wenn der Kampf wieder heißer wird. Es kann sich nur um Tage handeln.", sourceObjective = "Sprecht mit Yvera Dämmerschwinge, um nach Boralus zurückzukehren.", completion = "Ihr seid alle beschäftigt? Ausgezeichnet.\n\nDie Front in Arathi strikt zu verteidigen, ist entscheidend für die weitere Besatzung von Lordaeron durch die Allianz. Wir bedanken uns für Eure Unterstützung, sowohl jetzt als auch in dem unvermeidlichen Kampf, der uns bevorsteht.", sourceObjectiveStatus = "unverified-source-field" }
quests[53205] = { id = 53205, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spenden für das Arathihochland: Moneliterz", description = "Ihr seht aus wie ein <Kerl, der/Mädel> das;, nie ohne jede Menge Erz im Gepäck unterwegs ist! Wenn dem so ist, käme uns Eure Hilfe sehr gelegen dabei, ein bisschen mehr von dem Zeug für unsere Kriegsanstrengungen zu sammeln.\n\nAlso, hättet Ihr etwas Erz übrig?", sourceObjective = "Sammelt 20 Brocken Moneliterz für Brandal Dunkelbart im Hafen von Boralus.", progress = "Ihr seht aus wie ein Kerl, der nie ohne jede Menge Erz im Gepäck unterwegs ist!\n\nAlso, hättet Ihr was davon übrig?", completion = "Aha! Wusste doch, dass ich Euch richtig eingeschätzt habe!\n\nIch habe das daran erkannt, dass Eure Hosen ein wenig durchgehangen haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[53207] = { id = 53207, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schatten der Kriegsfront", description = "Unser Fokus muss über die Grenzen von Kul Tiras hinausgehen. Die Allianz stellt sich unseren Streitkräften in anderen Teilen der Welt immer noch entgegen.\n\nUnser größtes Interesse gilt dabei dem Arathihochland in der Nähe von Burg Stromgarde. Wir haben unser Lager in der Gegend aufgeschlagen, um von dort aus Burg Stromgarde einzunehmen.\n\nSprecht mit Throk, dem für diese Kriegsfront verantwortlichen Rekrutierungsoffizier. <Ein guter/Eine gute:c> {class} wie Ihr ist bei ihm sicher gerne gesehen.", sourceObjective = "Meldet Euch bei Throk in Zuldazar.", completion = "Ihr seid wohl {name} von den Eidgebundenen, was?\n\nWillkommen. Wir haben schon von Euch gehört. Also, an die Arbeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[53208] = { id = 53208, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An die Front", description = "Wir sind im Arathihochland in einen Krieg verwickelt. Vorerst hat die Lage sich beruhigt, aber wenn die Kämpfe wieder aufflammen, brauchen wir Euch an der Front.\n\nDruza Netherfang betreibt ein Portal direkt nach Ar'gorok. Sie kann Euch helfen.", sourceObjective = "Sprecht mit Druza Netherfang, um Euch nach Ar'gorok teleportieren zu lassen und meldet Euch dann bei Wistel Silberfinger.", completion = "Krieg. Wie schrecklich er doch wäre, wenn man nicht solch fantastischen Profit aus ihm schlagen könnte.\n\nIhr seid {name}, richtig? Dann wollen wir mal anfangen.", sourceObjectiveStatus = "unverified-source-field" }
quests[53209] = { id = 53209, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beitrag für die Kriegsfront", description = "Eine gut ausgebildete Armee allein ist nicht alles, {name}. Wir brauchen auch Geld, Nahrung und Vorräte, um unsere Armee zu finanzieren, zu ernähren und kampfbereit zu halten.\n\nZeigt Euren Stolz und gebt, was Ihr könnt. Für die Horde!", sourceObjective = "Spendet etwas als Beitrag zu den Kriegsanstrengungen. Ihr könnt, Gold, Kriegsressourcen oder hergestellte Ausrüstung beisteuern. Nur bestimmte NSCs nehmen tägliche Spenden entgegen.", sourceObjectiveStatus = "unverified-source-field" }
quests[53210] = { id = 53210, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erkundung der Front", description = "Die Allianz hat nun seit einiger Zeit nicht mehr angegriffen. Und wir auch nicht, um ehrlich zu sein. Es sollte jetzt sicher genug sein, um die Lage da draußen auszukundschaften.\n\nMeldet Euch bei unseren Vorarbeitern in der Mine und dem Sägewerk. Es wäre gut, zu wissen, dass sie nicht Reißaus genommen haben und dem Tod in die Arme gelaufen sind. Unterwegs könnt Ihr Euch außerdem nebenbei ein Bild vom Terrain verschaffen.\n\nApropos, vielleicht könntet Ihr auch bei Fluggenieur Krazzel vorbeischauen. Dann könnt Ihr Euch Burg Stromgarde aus der Vogelperspektive anschauen und wisst, womit wir es zu tun haben.", sourceObjective = "Meldet Euch bei Vorarbeiter Drogg, Graul und Fluggenieur Krazzel.", completion = "Schon zurück von Eurer Erkundungstour? Und niemand wurde von der Allianz abgeschlachtet? Schön.\n\nÜbrigens bin ich froh, dass Ihr es heil zurückgeschafft habt, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[53211] = { id = 53211, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spenden für das Arathihochland: Heiltrank der Küste", description = "Man hat mir berichtet, dass unsere Verbündeten noch ein paar weitere Vorräte für die bevorstehende Schlacht beiseiteschaffen wollen. Wenn Euch ein paar Heiltränke der Küste unterkommen, würde ich sie nur zu gerne einlagern.", sourceObjective = "Sammelt 10 Heiltränke der Küste für Klara Strand im Hafen von Boralus.", progress = "Ihr habt nicht zufällig Heiltränke übrig?\n\nIch versuche, eine ordentliche Menge davon für die kommende Schlacht vorrätig zu halten.", completion = "Oh nein...\n\n<Chelsea fängt einen fallenden Trank auf, bevor er auf dem Boden aufschlägt.>\n\nDas war knapp!\n\nWenn ich sie fallen lasse, bringen sie uns nicht mehr viel, nicht wahr?\n\nDanke noch mal, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[53212] = { id = 53212, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zurück nach Zuldazar", description = "Das sollte vorerst reichen. Wir melden uns, wenn der Kampf wieder heißer wird. Es kann wirklich jeden Moment losgehen.", sourceObjective = "Sprecht mit Druza Netherfang, um nach Zuldazar zurückzukehren.", completion = "Willkommen zurück.\n\nWir müssen die Front in Arathi verteidigen, {name}. Wir werden um Eure Hilfe ersuchen, wenn es so weit ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[53213] = { id = 53213, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spenden für das Arathihochland: Manatrank der Küste", description = "Eine unserer letzten Lieferungen Alchemievorräte wurde auf dem Weg zum Lagerhaus abgefangen. Wir geben uns alle Mühe, unsere Lagerbestände wieder aufzufüllen, aber ich befürchte, wir werden unser Soll nicht erreichen.\n\nIhr wisst nicht zufällig, wo man zusätzliche Manatränke auftreiben könnte, oder?", sourceObjective = "Bringt 10 Manatränke der Küste zu Klara Strand im Hafen von Boralus.", progress = "Ich würde gerne einige Tränke beschaffen, die unsere Verbündeten in einer langen Schlacht auf den Beinen halten. Habt Ihr so etwas?", completion = "Genau so etwas habe ich gesucht.", sourceObjectiveStatus = "unverified-source-field" }
quests[53216] = { id = 53216, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spenden für das Arathihochland: Schimmerschuppe", description = "Ich mache es kurz: Wir brauchen mehr Schimmerschuppen!\n\nTut mir leid, dass ich so mit der Tür ins Haus falle, aber die Zeit ist knapp.\n\nWenn Ihr auf Euren Reisen auf Schimmerschuppen stoßt, wüsste ich sie sicher zu unserem Vorteil einzusetzen. Unsere Verbündeten gut auszurüsten, ist für die bevorstehende Schlacht von entscheidender Bedeutung, meint Ihr nicht?", sourceObjective = "Spendet 100 Schimmerschuppen an Charlane im Hafen von Boralus.", progress = "Die Ausrüstung unserer Verbündeten hat allerhöchste Priorität. Damit haben wir die nötigen Materialien, um dafür zu sorgen, dass niemand ungeschützt auf das Schlachtfeld zieht.", completion = "Mit Eurer Hilfe werden wir im Nu einen ordentlichen Vorrat anlegen!", sourceObjectiveStatus = "unverified-source-field" }
quests[53217] = { id = 53217, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spenden für das Arathihochland: Rauer Lederharnisch", description = "Nicht nur unsere Verbündeten müssen wir in der bevorstehenden Schlacht schützen, sondern auch unsere verlässlichen Reittiere!\n\nKönnt Ihr uns helfen, damit wir sicherstellen können, dass unsere Verbündeten die bestmögliche Rüstung für den bevorstehenden Kampf erhalten?", sourceObjective = "Sammelt 5 raue Lederharnische für Charlane im Hafen von Boralus.", progress = "Nicht nur unsere Verbündeten müssen wir in der bevorstehenden Schlacht schützen, sondern auch unsere Tiere.", completion = "Damit stellen wir sicher, dass unsere Reiter und Tiere gut vorbereitet sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[53218] = { id = 53218, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spenden für das Arathihochland: Monelitgehärtete Hufplatten", description = "Ein Kampf wird nicht dadurch entschieden, welche Seite die beste Rüstung oder die schärfsten Klingen hat, aber helfen tun sie allemal! Fest steht, dass nicht nur unsere Verbündeten Unterstützung brauchen, sondern auch unsere Kampfbegleiter.\n\nWenn Ihr also zusätzliche Hufplatten für unsere tapferen Tiere zur Verfügung stellen könnt, sorgen unsere Hufschmiede für den Rest.", sourceObjective = "Sammelt 2 monelitgehärtete Hufplatten für Brandal Dunkelbart im Hafen von Boralus.", progress = "Ein Kampf wird nicht dadurch entschieden, welche Seite die beste Rüstung oder die schärfsten Klingen hat, aber helfen tun sie allemal! Fest steht, dass nicht nur unsere Verbündeten Unterstützung brauchen, sondern auch unsere Kampfbegleiter.\n\nWenn Ihr also zusätzliche Hufplatten für unsere tapferen Tiere zur Verfügung stellen könnt, sorgen unsere Hufschmiede für den Rest.", completion = "Sehr großzügig von Euch, {name}. Die werden wir bestimmt gut gebrauchen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[53219] = { id = 53219, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spenden für das Arathihochland: Monelitgehärtete Steigbügel", description = "In Zeiten wie diesen ist es wichtig, dass man stets kampfbereit ist. Unsere Tiere mit passenden Steigbügeln auszustatten, ist schon ein Schritt in die richtige Richtung.\n\nAlso bringt mir ein paar, und wir werden sie gut zu nutzen wissen.", sourceObjective = "Sammelt 2 monelitgehärtete Steigbügel für Brandal Dunkelbart im Hafen von Boralus.", progress = "In Zeiten wie diesen ist es wichtig, dass man stets kampfbereit ist. Unsere Tiere mit passenden Steigbügeln auszustatten, ist schon ein Schritt in die richtige Richtung.\n\nAlso bringt mir ein paar, und wir werden sie gut zu nutzen wissen.", completion = "Sehr gute Arbeit, Bursche.\n\nIch bringe die sofort zu unseren Reitern.", sourceObjectiveStatus = "unverified-source-field" }
quests[53221] = { id = 53221, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Missionsbericht: Verschollener Nachschub", description = "Eure Anhänger haben Euch einen Bericht über die Mission im Geiernest geschickt.\n\nDarin steht, dass die Mission ein Erfolg war und die verschollen geglaubte Nachschublieferung geborgen werden konnte.\n\nBringt den Bericht zu Hochkommandant Wyrmbann an Bord der Erlösenden Winde.", sourceObjective = "Bringt den Missionsbericht zu Halford Wyrmbann.", progress = "Gibt es Neuigkeiten über die Mission im Geiernest?", completion = "Die Mission zur Bergung der Vorräte scheint ein Erfolg gewesen zu sein. Gut gemacht, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[53222] = { id = 53222, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Benötigte Vorräte", description = "Die Mission zur Bergung des Nachschubs war ein voller Erfolg. Gut gemacht, {name}.\n\nDie fragliche Lieferung wurde von Batz Kurbeltuff im Geiernest bestellt. Ihr solltet am Außenposten in Vol'dun vorsprechen und sicherstellen, dass alle fehlenden Vorräte da sind.\n\nBegebt Euch zum Geiernest in Vol'dun und sprecht mit Batz Kurbeltuff.", sourceObjective = "Sprecht mit Batz Kurbeltuff.", completion = "Schön, Euch zu sehen, {name}! Ohne Eure Hilfe wären die von mir bestellten Fässer verloren gewesen! Trinkt so viel Ihr wollt. Los, lasst das Gebräu in rauen Mengen fließen!", sourceObjectiveStatus = "unverified-source-field" }
quests[53223] = { id = 53223, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spenden für das Arathihochland: Gegrillter Wels", description = "Seid gegrüßt, <Reisender/Reisende>.\n\nMan hat mich gebeten, dafür zu sorgen, dass unsere Nahrungsmittelvorräte nie zur Neige gehen, aber in letzter Zeit wird der Fisch knapp. Habt Ihr etwas, was Ihr gern spenden würdet?", sourceObjective = "Sammelt 5 Stücke gegrillten Wels für Senedras im Hafen von Boralus.", progress = "Man hat mich gebeten, dafür zu sorgen, dass unsere Nahrungsmittelvorräte nie zur Neige gehen, aber in letzter Zeit wird der Fisch knapp.\n\nHabt Ihr welchen, den Ihr gern spenden würdet?", completion = "Das dürfte reichen! Ich werde dafür sorgen, dass unsere Verbündeten wohlgenährt in die Schlacht ziehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[53224] = { id = 53224, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spenden für das Arathihochland: Gewürzte Lenden", description = "Gutes, herzhaftes Fleisch ist genau die Nahrung, die unsere Verbündeten verdienen, bevor sie in die Schlacht ziehen. Außerdem lässt sich damit ein zünftiger Eintopf zubereiten, genau wie ihn unsere Truppen lieben, wenn die Winde gut stehen und die Nächte kälter werden.\n\nWenn Ihr mir ein paar frische gewürzte Lenden besorgt, bringe ich sie gerne zu unseren Versorgungsoffizieren.", sourceObjective = "Sammelt 20 gewürzte Lenden für Senedras im Hafen von Boralus.", progress = "Herzhaftes Fleisch ist genau die Nahrung, die unsere Verbündeten verdienen.\n\nWenn Ihr mir ein paar frische gewürzte Lenden besorgt, bringe ich sie gerne zu unseren Versorgungsoffizieren.", completion = "Ich werde sie sofort zu unseren Versorgungsoffizieren bringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[53225] = { id = 53225, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spenden für das Arathihochland: Großmeerwels", description = "Fisch... den gibt's heut Abend auf den Tisch! Sagen jedenfalls unsere Versorgungsoffiziere. Und diese Woche dreht sich bei unseren Gerichten alles um eine köstlichen Zutat: Wels.\n\nWenn wir unsere Verbündeten gut ernähren und mit Fisch versorgen wollen, sollten wir schnellstens mehr Vorräte sammeln und mit den Vorbereitungen beginnen.\n\nWenn Ihr beim Schwimmen mal in einem Schwarm Welse geraten solltet, könnt Ihr sie mir gerne für unsere Vorräte bringen.", sourceObjective = "Sammelt 40 Großmeerwelse für Senedras im Hafen von Boralus.", progress = "Wenn wir unsere Verbündeten gut ernähren und mit Fisch versorgen wollen, sollten wir dafür sorgen, dass wir einen entsprechenden Vorrat haben.\n\nFalls Ihr also einmal gar nicht wisst, wohin mit Eurem ganzen Wels, könnt Ihr mir den gerne für unsere Vorräte bringen.", completion = "Sieht aus, als wäre das große Fischmahl noch nicht zu Ende.\n\nUnsere Verbündeten werden hocherfreut sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[53226] = { id = 53226, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spenden für das Arathihochland: Gischtvernebeltes Leinen", sourceObjective = "Sammelt 40 Stücke gischtvernebeltes Leinen für Faella im Hafen von Boralus.", progress = "So etwas wie zu viel Leinenstoff gibt es nicht. Ich habe lieber das Problem einer aufwendigen Grundversorgung, als irgendwann ohne Material dazustehen.", completion = "Wie aufmerksam von Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[53227] = { id = 53227, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spenden für das Arathihochland: Schlachtflagge: Geist der Freiheit", sourceObjective = "Sammelt 2 Schlachtflaggen: Geist der Freiheit für Faella im Hafen von Boralus.", progress = "Ich habe ein Auge für Qualität, wenn es um Handarbeit geht. Aber ich suche besonders nach einem Gegenstand, der uns auf dem Schlachtfeld sehr helfen könnte.", completion = "Fabelhafte Arbeit, {name}. Wunderschön.", sourceObjectiveStatus = "unverified-source-field" }
quests[53228] = { id = 53228, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spenden für das Arathihochland: Schlachtflagge: Phalanxverteidigung", sourceObjective = "Sammelt 2 Schlachtflaggen: Phalanxverteidigung für Faella im Hafen von Boralus.", progress = "Fein gewobener Stoff und handgeschneiderte Erzeugnisse sind nicht alles. Unsere Hingabe spiegelt sich in unseren Werken wieder und dient unseren Truppen auf dem Schlachtfeld als Fanal der Hoffnung.\n\nUnd nach solch einem Gegenstand suche ich, hergestellt von einem hochbegabten Schneider. Habt Ihr so etwas in der Art gesehen?", completion = "Welch' wunderschöne Handwerkskunst. Ich kann mich zwar gar nicht daran sattsehen, doch leider muss ich mit unseren Vorbereitungen fortfahren.\n\nHabt vielen Dank.", sourceObjectiveStatus = "unverified-source-field" }
quests[53229] = { id = 53229, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spenden für das Arathihochland: Ring - Siegel des kritischen Trefferwerts", sourceObjective = "Sammelt 2 Ringe - Siegel des kritischen Trefferwerts für Finja Fidibus im Hafen von Boralus.", progress = "Ich war schon fast fertig damit, die Aufträge für die nächste Lieferung abzuschließen, da ist mir aufgefallen, dass ich gar keine Materialien mehr habe!\n\nDenkt Ihr, Ihr könntet mir dabei helfen, die ausstehenden Bestellungen zu bedienen?", completion = "Danke, dass Ihr uns über Wasser haltet. Wo wären wir nur ohne großzügige Leute wie Euch?", sourceObjectiveStatus = "unverified-source-field" }
quests[53230] = { id = 53230, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spenden für das Arathihochland: Ring - Siegel der Vielseitigkeit", sourceObjective = "Sammelt 2 Ringe - Siegel der Vielseitigkeit für Finja Fidibus im Hafen von Boralus.", progress = "Ich weiß, es ist ein bisschen kurzfristig, aber ich versuche, noch ein paar Verzauberungen für unsere nächste Lieferung zu finden.", completion = "Gut Arbeit! Wisst Ihr, Ihr seid der Grund, weshalb wir uns so schnell vorbereiten können.\n\nTausend Dank!", sourceObjectiveStatus = "unverified-source-field" }
quests[53231] = { id = 53231, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spenden für das Arathihochland: Düsterstaub", sourceObjective = "Sammelt 20 Waffe - Unbeirrbare Navigation für Finja Fidibus im Hafen von Boralus.", progress = "Ich konnte bis vor kurzem noch mit den Bestellungen mithalten. Doch jetzt wird es ohne zusätzliche Hilfe knapp.\n\nWärt Ihr dazu bereit, ein paar Materialien zu spenden?", completion = "Donnerwetter! Ich wusste, dass ich mich auf Euch verlassen kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[53232] = { id = 53232, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spenden für das Arathihochland: Brandmunition", description = "Auch wenn wir über gesunde Munitionsbestände verfügen, bleibt es meine Pflicht, zusätzliche Ressourcen zu finden, vor allem solche, die schwerer zu beschaffen sind.\n\nHeute suche ich nach einer ganz bestimmten Art von Munition, und zwar Brandmunition. Ich könnte Eure Hilfe wirklich brauchen, um welche aufzuspüren.", sourceObjective = "Sammelt 2 Teile Brandmunition für Norbert Klickritzel im Hafen von Boralus.", progress = "Auch wenn wir über gesunde Munitionsbestände verfügen, bleibt es meine Pflicht, zusätzliche Ressourcen zu finden, vor allem solche, die schwerer zu beschaffen sind.\n\nWürdet Ihr mir Bescheid sagen, wenn Euch Munition mit entzündlichen Eigenschaften in die Hände fällt?", completion = "Ich werde vorsichtig damit umgehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[53233] = { id = 53233, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spenden für das Arathihochland: Frostversetzte Munition", description = "He da!\n\nLaut Anweisungen von ganz oben brauchen wir mehr Munition! Etwas mit ein bisschen mehr Kick. Etwas, das niemand erwartet!\n\nNach allem, was ich gehört habe, gibt es eine spezielle frostbasierte Munition, die nur die erfahrensten Ingenieure herstellen. Unsere Munitionsoffiziere wären sicher begeistert, wenn Ihr ein paar Stück davon für mich auftreiben könntet!\n\nVielleicht darf ich sogar ein Exemplar behalten, um es zu untersuchen!", sourceObjective = "Sammelt 2 Teile frostversetzte Munition für Norbert Klickritzel im Hafen von Boralus.", progress = "Ich habe gehört, dass es eine spezielle frostbasierte Munition gibt, die nur die erfahrensten Ingenieure herstellen. Unsere Munitionsoffiziere wären sicher begeistert, wenn Ihr ein paar Stück davon für mich auftreiben könntet!", completion = "Beeindruckend! Die sind einfach großartig! Die Qualität der Arbeit allein ist... \n\nVerzeiht, ich lasse mich manchmal mitreißen.\n\nPasst auf Euch auf!", sourceObjectiveStatus = "unverified-source-field" }
quests[53234] = { id = 53234, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spenden für das Arathihochland: B.R.U.T.Z.L.", description = "Man weiß nie, wann man es auf dem Schlachtfeld so richtig krachen lassen muss, versteht Ihr? Zum Glück können wir für alle Eventualitäten planen!\n\nWir sind im Begriff, einen besonderen Vorrat an Sprengstoff speziell für jene Situationen anzulegen, in denen wir unseren Standpunkt mit etwas mehr... Nachdruck vermitteln müssen. Ich habe die Liste um ein gewisses Element ergänzt.\n\nWenn Ihr etwas davon übrig habt, werde ich sicherstellen, dass es gut genutzt wird.", sourceObjective = "Sammelt 3 B.R.U.T.Z.L. für Norbert Klickritzel im Hafen von Boralus.", progress = "Wir sind im Begriff, einen besonderen Vorrat an Sprengstoff speziell für jene Situationen anzulegen, in denen wir unseren Standpunkt mit etwas mehr... Nachdruck vermitteln müssen. Ich habe die Liste um ein gewisses Element ergänzt.\n\nWenn Ihr etwas davon übrig habt, werde ich sicherstellen, dass es gut genutzt wird.", completion = "Was für ein Fund!\n\nIch werde dafür sorgen, dass die vorsichtig behandelt werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[53235] = { id = 53235, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spenden für das Arathihochland: Kriegsrolle der Intelligenz", description = "Die Erleuchtung erhellt uns den Weg zum Sieg. In der Schlacht kämpfen wir als eine Einheit.\n\nTeilt Eure Erkenntnisse und Fähigkeiten mit mir und man wird Euch Eure Großzügigkeit nie vergessen.", sourceObjective = "Sammelt 3 Kriegsrollen der Intelligenz für Liao im Hafen von Boralus.", progress = "Geistige Erleuchtung bietet Gelegenheiten für den Sieg.", completion = "Für diese Gabe gilt Euch mein tiefster Dank.", sourceObjectiveStatus = "unverified-source-field" }
quests[53236] = { id = 53236, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spenden für das Arathihochland: Kriegsrolle der Seelenstärke", sourceObjective = "Sammelt 3 Kriegsrollen der Seelenstärke für Liao im Hafen von Boralus.", progress = "In schwierigen Situationen bietet sich die Gelegenheit, Stärke und Durchhaltevermögen zu zeigen.", completion = "Mögen die Vorbereitungen uns leiten und die Tapferkeit von innen heraus leuchten.", sourceObjectiveStatus = "unverified-source-field" }
quests[53237] = { id = 53237, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spenden für das Arathihochland: Kriegsrolle des Schlachtrufs", sourceObjective = "Sammelt 3 Kriegsrolle des Schlachtrufs für Liao im Hafen von Boralus.", progress = "Mit Vorbereitungen kommt der Erfolg.", completion = "Ich danke Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[53238] = { id = 53238, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spenden für das Arathihochland: Vielseitiger Kyanit", sourceObjective = "Sammelt 20 Stücke vielseitigen Kyanit für Larold Kyne im Hafen von Boralus.", progress = "Unsere Edelsteinvorräte gehen zur Neige. Wir würden alles, was Ihr erübrigen könnt, sehr zu schätzen wissen.", completion = "Fabelhaft.", sourceObjectiveStatus = "unverified-source-field" }
quests[53239] = { id = 53239, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spenden für das Arathihochland: Kantiges Viridium", sourceObjective = "Sammelt 15 Stücke kantiges Viridium für Larold Kyne im Hafen von Boralus.", progress = "Wir brauchen mehr Edelsteine!", completion = "Wunderbare Exemplare.\n\nDanke für Eure Unterstützung.", sourceObjectiveStatus = "unverified-source-field" }
quests[53240] = { id = 53240, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spenden für das Arathihochland: Tödlicher Solstein", sourceObjective = "Sammelt 20 Stücke tödlichen Solstein für Larold Kyne im Hafen von Boralus.", progress = "Habt Ihr welche davon in letzter Zeit gesehen?", completion = "Ihr seid wirklich ein Schatz, wisst Ihr?", sourceObjectiveStatus = "unverified-source-field" }
quests[53241] = { id = 53241, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spenden für das Arathihochland: Manatrank der Küste", progress = "Ich weiß, Ihr denkt, dass ich bald wieder keine Materialien mehr hab'. Und ich versuch' es erst gar nich', Euch vom Geg'nteil zu überzeug'n.\n\nWenn Ihr mir also 'n paar Manatränke besorg'n würdet, könnt' ich gleich wieder an die Arbeit geh'n und uns auf die kommende Schlacht vorbereit'n.", completion = "Ich werd' sie weiterreich'n.\n\nDanke für Eure Spende." }
quests[53242] = { id = 53242, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spenden für das Arathihochland: Heiltrank der Küste", progress = "'n paar Heiltränke würd'n sich in unser'm Vorrat gut mach'n. Bringt mir 'nen Schwung und ich sorg' dafür, dass sie dort ankomm'n, wo sie gebraucht werd'n.", completion = "Ich wusste, ich kann auf Euch zähl'n." }
quests[53243] = { id = 53243, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spenden für das Arathihochland: Rauer Lederharnisch", progress = "Nicht nur unsere Reiter sollten gepanzert das Schlachtfeld betreten, wir sollten auch auf den Schutz unserer Reittiere achten.\n\nWenn Ihr mir also einen Vorrat an Harnischen besorgen könntet, werde ich persönlich sicherstellen, dass unsere Kavallerie gut für den Kampf gerüstet ist, wenn die nächste Schlacht kommt.", completion = "Ich danke Euch, {name}. Ich werde dafür sorgen, dass unsere Verbündeten die Schutzausstattung bekommen, die sie verdienen." }
quests[53244] = { id = 53244, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spenden für das Arathihochland: Schimmerschuppe", progress = "Rüstung ist knapp. Und wenn wir nicht bald eine große Lieferung weiterer Materialien hereinbekommen, werden wir so schnell nirgendwohin aufbrechen.", completion = "Eine Lieferung wie diese wird uns erst einmal eine Weile beschäftigen.\n\nDanke für Eure Hilfe." }
quests[53245] = { id = 53245, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spenden für das Arathihochland: Monelitgehärtete Hufplatten", progress = "Noch ein paar Hufplatten und die nächste Lieferung ist komplett.\n\nWenn Ihr auf Euren Reisen noch welche auftreibt, wisst Ihr ja, wo Ihr mich findet.", completion = "Gute Arbeit. Die kommen sofort in unsere nächste Lieferung." }
quests[53246] = { id = 53246, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spenden für das Arathihochland: Monelitgehärtete Steigbügel", progress = "Unsere Kavallerie braucht neue Steigbügel, bevor sie in die Schlacht zieht.", completion = "Beste Handwerkskunst. Habt Ihr die selbst gefertigt?" }
quests[53247] = { id = 53247, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spenden für das Arathihochland: Schlachtflagge: Geist der Freiheit", progress = "Schlachtstandarten sind sehr gefragt.", completion = "Habt Ihr das etwa gefertigt?\n\nIch habe noch nie solch feine Stickereien gesehen." }
quests[53248] = { id = 53248, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spenden für das Arathihochland: Schlachtflagge: Phalanxverteidigung", progress = "Wir müssen unseren Verbündeten die Mittel in die Hand geben, mit denen sie ihre Verteidigung stärken können.", completion = "Das ist wirklich ein prächtiges Stück. Ich werde dafür sorgen, dass wir davon guten Gebrauch machen." }
quests[53249] = { id = 53249, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spenden für das Arathihochland: Gischtvernebeltes Leinen", progress = "Es ist besser, gut vorbereitet zu sein, als an Versorgungsknappheit zu leiden. Wenn Ihr also etwas Leinenstoff abzugeben habt, werden wir ihn sicher zu verwenden wissen.", completion = "Sehr großzügig von Euch, {name}." }
quests[53250] = { id = 53250, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spenden für das Arathihochland: Kriegsrolle der Seelenstärke", progress = "Nicht jeder wurde zum mutigen Krieger geboren, aber wer sagt, dass man sich nicht ab und zu wie einer benehmen kann?", completion = "Die sind genau richtig." }
quests[53251] = { id = 53251, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spenden für das Arathihochland: Kriegsrolle des Schlachtrufs", progress = "Die Schriftrolle, die ich suche, entfaltet bei Gebrauch eine sehr große Wirkung. Was meint Ihr? Seid Ihr in der Lage, so etwas aufzutreiben?", completion = "Ja. Das sollte genügen." }
quests[53252] = { id = 53252, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spenden für das Arathihochland: Kriegsrolle der Intelligenz", progress = "Jahrelange Studien haben es uns ermöglicht, Schriftrollen zu erschaffen, die die Intelligenz erhöhen. Habt Ihr in letzter Zeit so etwas gesehen? Ich würde sterben, um eine in die Hände zu bekommen.", completion = "Gute Arbeit." }
quests[53253] = { id = 53253, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spenden für das Arathihochland: Ring - Siegel der Vielseitigkeit", sourceObjective = "Sammelt 2 Ringe - Siegel der Vielseitigkeit für Uma'wi im Hafen von Zandalar.", progress = "Wenn Ihr was übrig habt, was uns helf'n könnte, kommt einfach wieder zu mir, ich geh' nirgendwohin.", completion = "Ah, ja. Genau danach hab' ich gesucht.", sourceObjectiveStatus = "unverified-source-field" }
quests[53254] = { id = 53254, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spenden für das Arathihochland: Ring - Siegel des kritischen Trefferwerts", sourceObjective = "Sammelt 2 Ringe - Siegel des kritischen Trefferwerts für Uma'wi im Hafen von Zandalar.", progress = "Rüstung, Schwerter, Speere... Wir werd'n bereit sein. Fehl'n nur noch 'n paar mehr Verzauberungen.", completion = "Sehr schön.", sourceObjectiveStatus = "unverified-source-field" }
quests[53255] = { id = 53255, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spenden für das Arathihochland: Düsterstaub", sourceObjective = "Sammelt 20 Waffen - Unbeirrbare Navigation für Uma'wi im Hafen von Zandalar.", progress = "Mit speziell'n mächtigen Verzauberungen ham unsre Verbündet'n vielleicht 'ne Chance, die nächste Schlacht zu gewinn'.\n\nMeint Ihr, Ihr findet welche auf Euern Reis'n?", completion = "Ihr könnt wohl Gedank'n les'n.", sourceObjectiveStatus = "unverified-source-field" }
quests[53256] = { id = 53256, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spenden für das Arathihochland: Tödlicher Solstein", progress = "Habt Ihr ein paar Edelsteine für mich?", completion = "Die sind sogar noch besser." }
quests[53257] = { id = 53257, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spenden für das Arathihochland: Vielseitiger Kyanit", progress = "Habt Ihr in letzter Zeit etwas Interessantes gefunden?", completion = "Besten Dank." }
quests[53258] = { id = 53258, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spenden für das Arathihochland: Kantiges Viridium", progress = "Ich hätte zu gern ein paar Edelsteine. Habt Ihr welche übrig?", completion = "Ja. Die sind genau richtig." }
quests[53259] = { id = 53259, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spenden für das Arathihochland: B.R.U.T.Z.L.", progress = "Wir machen gute Fortschritte bei der Munition. Wir brauchen nur noch ein bisschen mehr Dampf, wenn Ihr wisst, was ich meine.", completion = "Kaaaaa-BUMMM! Hah!\n\nIch kann es kaum erwarten, die in Aktion zu sehen." }
quests[53260] = { id = 53260, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spenden für das Arathihochland: Brandmunition", progress = "Wir haben mittlerweile eine ganze Menge Munition auf Lager. Aber wir suchen immer nach etwas, das richtig Dampf hat.", completion = "Ich kann es kaum erwarten, die in Aktion zu sehen!" }
quests[53261] = { id = 53261, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spenden für das Arathihochland: Frostversetzte Munition", progress = "Wisst Ihr, was unsere Feinde wirklich überraschen würde? Das Unerwartete.\n\nUnd ich habe da genau das Richtige.", completion = "Das werden die niemals kommen sehen!" }
quests[53262] = { id = 53262, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spenden für das Arathihochland: Gewürzte Lenden", progress = "Habt Ihr ein paar Lenden, die Ihr gerne spenden würdet?", completion = "Sehr großzügig von Euch." }
quests[53263] = { id = 53263, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spenden für das Arathihochland: Gegrillter Wels", progress = "Fisch ist ausgesprochen nahrhaft.", completion = "Das ist eine wahre Gaumenfreude." }
